insert into public.activity_overviews (slug, overview, updated_at) values
  ($s$economics/mini/stock_index_lab$s$, $ov$코스피·코스닥·코스피200·나스닥 등 주요 주가지수의 10년 실측 시계열을 연·월·일 주기와 '100 기준' 상대변화로 비교하고, 각 지수에 어떤 종목이 시가총액 순으로 담겨 있는지 트리맵으로 살펴본 뒤, 코스피 시가총액 상위 15종목으로 만든 미니 지수에서 특정 기업의 주가를 직접 올리고 내리며 지수가 시가총액 가중 방식으로 어떻게 움직이는지 시뮬레이션하는 활동. 주가와 시가총액의 차이, 스케일이 다른 지수를 100 기준으로 공정하게 비교하는 방법, 그리고 시가총액이 큰 기업일수록 같은 주가 변동이 지수에 더 큰 영향을 준다는 점을 체험한다.$ov$, now()),
  ($s$economics/mini/gdp_growth_lab$s$, $ov$World Bank(세계개발지표) 공식 데이터로 한국의 명목·실질 GDP, GNI, 경제성장률, GDP 디플레이터, 소비자물가지수의 30년(1995~2024) 흐름을 규모·성장·물가 세 관점으로 비교하고, 214개국의 GDP·1인당 GDP·성장률·1인당 GNI를 연도별 세계지도 음영과 정렬 표로 탐색하며 특정 국가를 골라 그 나라의 시계열 추이까지 살펴본 뒤, 명목·실질 GDP와 GDP 디플레이터를 직접 계산해 보고 GDP·GNP·GNI 판정 퀴즈로 개념 차이를 확인하는 활동. 명목과 실질의 구분, 물가지표(디플레이터·CPI)의 의미, 경제 규모(총액)와 국민 생활수준(1인당)의 차이, 그리고 생산의 '장소(GDP)'와 '국적·소득(GNP·GNI)' 기준의 차이를 공식 데이터로 체험한다.$ov$, now()),
  ($s$economics/mini/percentage_point_lab$s$, $ov$경제지표의 증감을 말할 때 자주 혼동되는 '퍼센트(%)'와 '퍼센트포인트(%p)'의 차이를, 실제 기사 사례(한국은행 기준금리 0.25%p 인상, 실업률 변화 등)와 흔한 혼용 오류(예: 점유율 2%→1%의 1%p 감소를 '50% 감소'로 부풀린 표현, 일본은행 재할인율 0.75%p 인하를 '0.75% 인하'로 쓴 신문 사례)로 살펴보고, 이전·이후 값을 직접 바꿔 %p 변화(두 값의 차이)와 %(기준 대비 상대변화)가 어떻게 다르게 계산되는지 확인한 뒤, 30초 제한시간 스피드 퀴즈로 %와 %p 구분 문제를 빠르게 풀어 보는 활동. 이미 백분율인 지표의 변화량은 %p로, 기준량 대비 상대적 변화는 %로 표현해야 함을 익힌다.$ov$, now()),
  ($s$economics/mini/employment_lab$s$, $ov$World Bank(세계개발지표, ILO 추정) 공식 데이터로 한국의 고용률·취업률·실업률 시계열(1995~2024)을 살펴보고, 물가상승률과 이들 고용지표가 어떤 관계로 함께 움직이는지 비교하며, 187개국의 고용률·실업률·취업률을 연도별 세계지도와 국가별 시계열로 탐색한 뒤, 취업자·실업자·비경제활동인구를 직접 조절해 15세 이상 인구의 구성을 시각화하며 취업률+실업률=100%이지만 고용률+실업률은 100%가 아님을 확인하는 활동. 고용률(분모 15세 이상 인구)과 취업률(분모 경제활동인구)의 차이, 경제활동인구·비경제활동인구 개념을 데이터와 조작으로 체험한다.$ov$, now()),
  ($s$economics/mini/exchange_rate_lab$s$, $ov$Frankfurter(유럽중앙은행 ECB 참조환율) 공식 데이터로 원(₩)을 기준으로 달러·위안·엔·유로·파운드 등 주요국 통화를 서로 환전(원↔외화, 외화↔외화)해 보는 환율 변환기와, 주요 통화의 과거 환율을 원 기준으로 일·월·연 주기와 100 기준 상대변화로 한 그래프에서 비교하는 시계열로 구성된 활동. 환율의 의미(1달러=OO원), 두 외국 통화 사이의 교차환율 계산, 원화 가치의 변화(강세·약세)와 서로 다른 통화의 변동을 공정하게 비교하는 방법을 조작하며 익힌다. 최신 환율은 새로고침으로 실시간 반영한다.$ov$, now()),
  ($s$economics/mini/exchange_impact_lab$s$, $ov$환율의 변동이 수출·수입·해외여행·유학·수입물가에 어떤 손익을 주는지 미국·일본·중국의 실제 환율 데이터와 국제 유가(WTI)로 탐구하는 활동. 환율 슬라이더를 움직여 달러 수출 매출, 해외 직구 비용, 여행 환전액, 유학 등록금, 원유 수입가격이 원화로 어떻게 달라지는지 시뮬레이션하고(환율 상승=원화 약세), 환율 변동이 우리 삶에 미치는 실생활 사례와 ''환율 상승은 무조건 좋다'' 같은 흔한 오해를 살펴본 뒤, 카드형 퀴즈로 각 주체의 유리·불리를 판정한다. 같은 환율 변동이 수출자에게는 유리하고 수입자에게는 불리하듯 이해관계가 엇갈림을, 국제 유가가 달러로 거래되어 환율이 오르면 수입 물가가 오른다는 점을 데이터로 체험한다.$ov$, now()),
  ($s$economics/mini/bigmac_index_lab$s$, $ov$The Economist의 빅맥지수 공식 오픈데이터로 54개국 빅맥의 달러 환산 가격과 미국 대비 고평가·저평가를 비교하고, 빅맥의 내재환율(구매력평가)과 실제 환율을 견주어 원화 등 각국 통화가 고평가·저평가되어 있는지 시계열과 함께 탐구하며, 빅맥 외에 아이폰·스타벅스 라떼처럼 각국에서 공통으로 팔리는 물품의 가격으로도 비슷한 물가·환율 지수를 만들어 세 지수를 비교하고, 세계은행 공식 물가수준지수와의 상관까지 산점도로 확인하는 활동. 같은 물건의 가격을 나라별로 비교하면 그 나라 돈의 실질 구매력을 가늠할 수 있다는 구매력평가(PPP)의 아이디어와, 어떤 물품을 기준으로 삼느냐에 따라 결과가 조금씩 달라짐을 실제 데이터로 체험한다.$ov$, now()),
  ($s$economics/mini/exchange_smart_lab$s$, $ov$실제 최신 환율(Frankfurter/ECB)로 은행·환전소의 환율 표기판(매매기준율·현찰 살 때·현찰 팔 때)을 재현해 원하는 통화로 환전하며 환전 수수료가 얼마나 드는지 체험하는 환전소 시뮬레이터와, 여행 환전 활동처럼 달러를 엔으로 바로 바꾸는 경우와 달러→원→엔으로 두 번 바꾸는 경우의 최종 금액을 비교해 환전 횟수가 많을수록 손해임을 확인하는 활동. 매매기준율과 살 때·팔 때 가격의 차이(수수료), 그리고 환전 횟수를 최소화하는 현명한 환전 방법을 조작하며 익힌다. 최신 환율은 새로고침으로 오늘자로 갱신한다.$ov$, now()),
  ($s$economics/mini/tax_lab$s$, $ov$대한민국 세금의 종류를 국세·지방세, 직접세·간접세, 보통세·목적세로 분류한 체계(국세청·행정안전부·관세청 현행 세법 기준)를 25개 세목 카드 뒤집기로 탐색하고, 하루 소비 시뮬레이터로 편의점 음료·외식·주유·자동차 보유·집 구입·해외직구 등에서 실제로 어떤 세금이 얼마나 부과되는지 실제 세율로 계산해 ''오늘 낸 세금 영수증''과 국세·지방세 비율로 확인하며, 세금 이름을 보고 국세/지방세 또는 직접세/간접세를 맞히는 분류 게임으로 마무리하는 활동. 각 세금의 정의·납세자·실생활 사례·세율을 다루며, 특히 부가가치세처럼 세금을 내는 사람(사업자)과 실제 부담하는 사람(소비자)이 다른 간접세의 특징을 체험한다.$ov$, now()),
  ($s$economics/mini/tax_rates_lab$s$, $ov$세계 여러 나라의 세율을 세계지도에 색으로 표시하고 복지 수준과 함께 비교하는 활동. 탭①에서는 가로축(세율: 개인소득세 최고세율 또는 국민부담률)과 세로축(복지 척도: 인간개발지수 HDI·행복지수·기대수명·사회복지지출)을 골라 산점도의 상관관계와 상관계수로 ''세금을 많이 걷는 나라가 정말 복지가 좋은가''를 탐구하고, 탭②에서는 세율과 한 해 걷힌 세금 총액(국민부담률×GDP)을 비교해 세율이 높은 나라와 세금 총액이 큰 나라가 다름을(세금 총액은 경제 규모에 크게 좌우됨) 확인한다. 데이터는 Our World in Data(UNDP·세계행복보고서·기대수명·조세수입·OECD 사회복지지출), World Bank(GDP), OECD·KPMG(소득세 최고세율) 공식 자료로, 척도별로 자료가 있는 국가만 지도와 산점도에 표시한다.$ov$, now()),
  ($s$economics/mini/income_tax_lab$s$, $ov$직접세인 소득세의 계산 과정을 네 탭으로 탐구하는 활동. ①총급여에서 근로소득공제·인적공제·국민연금·신용카드 등 공제를 차례로 빼 과세표준이 만들어지는 과정을 조작하고, ②과세표준에 국세청 종합소득세 기본세율(2023, 8구간)을 적용해 '구간별 누진세율 합산'과 '과세표준×세율−누진공제액' 두 방법이 항상 같은 산출세액을 준다는 것을 확인하며 소득세 함수 T(과세표준)의 연속성과 한계·실효세율을 그래프로 분석하고, ③낸 소득세로부터 과세표준을 역산(역함수)해 건강보험료로 소득을 추정하듯 소득을 거꾸로 가늠하며, ④여러 직업의 평균 연봉(고용노동부·워크넷 등 공신력 통계 개략치)으로 각 직업의 소득세와 실효세율을 비교해 누진세의 효과를 체감한다. 누진공제액의 의미, 소득세 함수의 연속성과 역함수, 누진세율 구조를 계산과 조작으로 익힌다.$ov$, now()),
  ($s$economics/mini/corporate_tax_lab$s$, $ov$직접세인 법인세의 계산과 실제 기업 데이터를 두 탭으로 탐구하는 활동. ①법인 종류(영리·비영리 / 조합)와 과세표준을 정하면 우리나라 법인세율표(2024, 영리 9~24% 4구간·조합 9·12%)로 법인세=과세표준×세율−누진공제액이 계산되는 과정을 단계별로 보여주고 구간별 누진 합산과 결과가 같음을 확인하며, ②삼성전자·SK하이닉스·현대자동차·NAVER·카카오 등 영리법인(연결)과 한살림사업연합(조합·별도)의 최근 5개년(2021~2025) 법인세비용을 DART 전자공시 실데이터로 선그래프와 표로 비교한다(기업 선택 시 자동 스케일). 법인 종류에 따른 세율 차이, 대기업과 조합의 법인세 규모 차이, 그리고 이익에 따라 법인세가 해마다 달라지고 적자·이연법인세로 환입(음수)이 나기도 함을 실제 자료로 체험한다.$ov$, now()),
  ($s$economics/mini/excise_tax_lab$s$, $ov$간접세인 개별소비세를 두 탭으로 탐구하는 활동. ①개별소비세법(2024) 품목별 세율 — 승용자동차 5%, 유흥음식 10%, 보석·귀금속·고급시계·가방·모피·가구는 기준가격 초과분 20%, 담배(궐련) 20개비당 594원, 골프장 12,000원·카지노 50,000원(1인 1회), 등유·부탄 등 — 로 구매 금액이나 수량에 따른 개별소비세를 계산하고(비율·기준가격 초과·정액 세 방식), ②정부가 경기 부양을 위해 자동차 개별소비세를 한시적으로 인하한 실제 이력(정상 5% ↔ 30% 인하 3.5% ↔ 코로나기 70% 인하 1.5%)을 바탕으로, 차량 공장도가를 정하면 개별소비세와 그에 연동된 교육세(개소세의 30%)·부가가치세까지 함께 줄어 세금 포함 가격이 얼마나 싸지는지(절약액) 비교한다. 개별소비세를 특정 물품·장소에만 매기는 까닭, 세금 위에 세금이 붙는 구조, 탄력세율 정책의 효과를 실제 세율과 사례로 체험한다.$ov$, now()),
  ($s$economics/mini/vat_lab$s$, $ov$간접세의 대표인 부가가치세를 세 탭으로 탐구하는 활동. ①토마토→파스타, 목화→티셔츠, 나무→책상, 부품→스마트폰 네 가지 공급망에서 생산·유통 단계 수(3~5단계)와 각 단계의 판매가를 직접 조작하며, 단계마다 부가가치(판매가−매입가)가 생기고 납부세액=매출세액−매입세액(부가가치의 10%)으로 계산되는 과정을 한 단계씩 공개해 확인하고, 각 단계가 나눠 낸 세액의 합이 언제나 최종 판매가의 10%(=최종 소비자가 부담한 부가가치세)와 같음을 확인하며, 매입세액 공제가 없다면 세금이 중복되어 얼마나 커지는지 비교한다. ②마트 진열대에서 장바구니를 담고 각 품목이 면세인지 과세인지 먼저 예상한 뒤 영수증을 발행해 채점하고, 면세 물품 가액·과세 물품 가액(표시가격÷1.1)·부가 가치세·합계가 계산되는 과정과 내가 낸 총액 중 부가세 비중을 확인한다(쌀·흰 우유·정육·도서·신문·지하철·의료 등 면세 ↔ 즉석밥·딸기 우유·소시지·생수·택시·카페 등 과세의 헷갈리는 짝 비교 포함). ③부가가치의 뜻, 납부세액 계산, 실제 부담자, 표시가격 속 부가세 역산, 면세 판별, 중복 과세, 간접세의 역진성을 묻는 9문항 카드 퀴즈로 정리한다. 근거는 부가가치세법 제30조(세율 10%)·제37조·제38조(매출세액−매입세액)·제26조(면세).$ov$, now()),
  ($s$economics/mini/customs_lab$s$, $ov$간접세인 관세를 세 탭으로 탐구하는 활동. ①WTO World Tariff Profiles의 주요 18개국 실행 MFN 관세율(전체·농산물·공산품 단순평균)을 막대로 비교해 우리나라가 공산품은 6.5%로 낮고 농산물은 56.9%로 매우 높다는 점을 확인하고, 관세청 관세율표의 우리나라 품목별 실행세율(인삼 754.3%·참깨 630%·쌀 513%·마늘 360%·쇠고기 40%·의류 13%·자동차 8%·노트북/휴대전화/반도체 0% 등)을 그룹별로 비교하며 국내 산업 보호와 WTO 정보기술협정(ITA) 무관세의 까닭을 찾는다. ②해외직구 관세 계산기 — 나라(미국·EU·영국·베트남·호주·중국·일본·인도)와 품목, 물품가격·배송비·환율을 조작하면 과세가격(CIF)→관세→수입 부가가치세(과세가격+관세의 10%)→최종 지불액이 단계별로 계산되고, 자가사용 소액물품 면세(150달러, 미국발 200달러) 적용 여부와 원산지증명서 제출 시 FTA 협정세율 0% 적용에 따른 절약액을 비교한다. ③우리나라가 발효한 FTA 22건 59개국을 발효 시기별로 색칠한 세계지도에서 확인하고, 협정을 누르면 해당 국가만 강조되며, 한·EU 27개국·한·아세안 10개국·RCEP 등 다자 협정과 일본과는 양자 FTA가 없다는 점을 짚는다. 관세가 국내 산업 보호에 쓰이고 지나치면 관세장벽으로 무역 갈등을 부른다는 점, 같은 물건도 원산지에 따라 세율이 달라진다는 점을 실제 자료와 계산으로 체험한다.$ov$, now()),
  ($s$economics/mini/interest_rate_lab$s$, $ov$여러 가지 이율을 두 탭으로 비교하는 활동. ①이율 변환기 — 연·반기·분기·월·주·일·시·분·초 아홉 단위 중 어느 칸에 이율을 입력해도 나머지가 모두 다시 계산되며, 같은 이율을 단리(비례: 이율÷기간 수)로 환산한 값과 복리(실효: (1+단위이율)^(1년의 기간 수)−1)로 환산한 값을 나란히 보여 준다(예: 월 1% → 단리 연 12%, 복리 연 12.68%). 명목 연이율과 실효 연이율, 원금 100만원의 1년 뒤 원리합계 차이를 확인하고, 이어서 연이율은 그대로 둔 채 이자 계산 횟수만 연 1회→반기→분기→월→주→일→시→분→초로 늘리면 원리합계가 무한히 커지지 않고 연속복리 P·e^r에 수렴함을 표와 막대로 관찰한다(연이율 100%면 100만원 → 271만 8,282원 = 100만원×e). ②우리 주변의 이율 — 저축(수시입출금 0.1%·파킹통장·정기예금·정기적금·주택청약종합저축 3.1%·청년도약계좌), 대출(학자금대출 1.7%·주택담보대출·신용대출·카드 할부/현금서비스/리볼빙·법정 최고금리 20%·연체이자 약정금리+3%p·불법 일수 연 36.5%), 나라·연금(한국은행 기준금리·국고채 3년·국민연금 기금 수익률), 물가(소비자물가 상승률) 19개 사례를 카드로 보여 주고, 원금·기간·단리/복리를 조작하면 각 사례의 이자와 원리합계, 72의 법칙에 따른 2배 기간이 함께 계산된다. 이자소득세 15.4%와 적금 이자가 표시 금리의 절반쯤인 까닭도 계산으로 확인한다. 법정 이율은 근거 법령을, 시장금리는 공시 기관과 기준 시점을 카드마다 표기한다.$ov$, now()),
  ($s$economics/mini/simple_interest_lab$s$, $ov$단리의 원리합계를 두 탭으로 탐구하는 활동. ①단리 시뮬레이터 — 원금 A, 이율 r(연이율/월이율 선택), 기간 n을 조작하면 매 기간 붙는 이자 rA, 이자 총액 A·r·n, 원리합계 S = A(1+rn)이 즉시 계산되고, 시점별 발생한 이자·누적 이자·원리합계와 기호식(A, A+rA, A+2rA, …)을 표로, 시간에 따른 원리합계를 직선 그래프로 보여 준다. 시점 슬라이더로 특정 시점의 값을 짚어 볼 수 있고, ‘복리와 비교하기’를 켜면 같은 조건의 복리 곡선이 겹쳐 그려져 단리가 왜 직선인지(매 기간 이자가 rA로 일정) 확인하며, 원리합계가 첫째항 A+rA·공차 rA인 등차수열임을 수치와 함께 정리한다. ②단리 미션 — 정기예금(200만원 연 3.5% 단리), 대출 이자(300만원 연 6% 단리를 8개월만 사용, 연이율↔월이율 환산), 학자금대출(400만원 연 1.7% 단리와 연 6% 신용대출의 이자 비교), 그리고 서로 다른 단위로 제시된 두 상품 중 유리한 쪽 고르기(새싹은행 월이율 0.3% 단리 ↔ 구름은행 연이율 3% 단리, 500만원 3년) 네 미션을 각각 3~4단계로 나눠, 앞 단계를 맞혀야 다음 단계가 열리는 방식으로 풀며 힌트·해설·뱃지를 제공한다. 이율을 비교할 때 기간 단위를 먼저 통일해야 한다는 점(월 0.3% = 연 3.6%)을 계산으로 체험한다. 학자금대출 연 1.7%는 한국장학재단이 2022년 2학기부터 유지 중인 실제 금리이며, 세금은 계산에 넣지 않았다.$ov$, now()),
  ($s$economics/mini/compound_interest_lab$s$, $ov$복리의 원리합계를 세 탭으로 탐구하는 활동. ①복리 시뮬레이터 — 원금 A, 이율 r(연이율/월이율 선택), 기간 n을 조작하면 매 기간 새로 붙는 이자(직전 원리합계×r)가 점점 커지는 모습과 원리합계 S = A(1+r)^n을 표(시점·발생한 이자·누적 이자·원리합계·식 A(1+r)^k)와 곡선 그래프로 보여 주고, 시점 슬라이더로 특정 시점을 짚으며 원리합계가 첫째항 A(1+r)·공비 (1+r)인 등비수열임을 정리한다(단리는 더하기라 직선·등차수열, 복리는 곱하기라 곡선·등비수열). ②단리 vs 복리 — 같은 원금·이율·기간에서 두 그래프를 겹쳐 그리고 사이 영역을 색칠해 격차가 벌어지는 모습을 보여 주며, 시점별 비교표와 차이·이자 배수, 원금이 2배가 되는 시점(단리 1/r, 복리 log2/log(1+r))을 나란히 제시해 기간이 길수록·이율이 높을수록 격차가 커짐을 확인한다. ③이율 단위를 바꾸면? — 연이율 r을 월이율 r/12로 바꾸고 기간을 12배 했을 때 결과가 같을지 먼저 예측하게 한 뒤, 단리는 A(1+rn) = A(1+(r/12)(12n))으로 완전히 같고 복리는 A(1+r)^n < A(1+r/12)^(12n)로 달라짐을 2×2 표와 네 그래프(단리 두 선은 포개지고 복리 두 선은 벌어짐)로 확인하며, 이자를 붙이는 주기를 연 1회에서 반기·분기·월·일로 잘게 나눌수록 실효 연이율과 원리합계가 커지지만 A·e^(rn)에 수렴함((1+r/m)^m → e^r)까지 다룬다. 사례 이율(정기예금 3.5%, 카드 현금서비스 17.5%, 국민연금 기금 장기 연평균 6%)은 2025년 기준 대표값이며 이자소득세는 반영하지 않았다.$ov$, now()),
  ($s$economics/mini/rule_of_72_lab$s$, $ov$맨해튼 24달러 이야기로 복리의 위력을 체감하고 72의 법칙을 확인하는 두 탭 활동. ①약 100초 분량의 시네마틱 애니메이션(9장면, 재생·탐색·챕터 이동 가능)으로 1626년 네덜란드 서인도회사 총독 피터 미누이트가 레나페족에게서 60길더어치 물품으로 맨해튼 섬을 사들인 일, 그 값이 1846년에 24달러로 환산된 사연, 그 24달러를 연 8% 복리로 400년 굴렸을 때의 금액(약 562조 달러)을 로그 눈금 성장 곡선과 연도·금액 카운터로 보여 주고, 뉴욕시 예산·맨해튼 부동산·애플 시가총액·미국 GDP·세계 GDP와 로그 막대로 비교하며, 같은 400년이라도 연 2·4·6·8%가 얼마나 달라지는지(8%와 6%가 약 1,767배 차이) 대비한 뒤 72의 법칙(8%면 9년마다 두 배, 400년이면 약 44번)을 예고한다. 이어 이율·기간을 직접 조작하는 24달러 타임머신과, 서인도회사(동인도회사가 아님)·물품 지급·24달러의 유래·아인슈타인 인용의 출처 불명을 짚는 사실 확인 카드를 제공한다. ②72의 법칙 n = 72/r을 이율·원금을 바꿔 가며 단계별로 확인(72÷r로 기간을 어림 → (1+r/100)^n 계산 → 원금이 몇 배가 되는지)하고, 교과서 표(r = 1·2·3·4… → 2.047·2.040·2.033·2.026)를 정확한 배가 기간 log2/log(1+r) 및 오차와 함께 재현하며, 목표 기간 안에 두 배로 만들 이율을 역으로 구하고(10년이면 7.2%), 두 배 사다리로 2·4·8·16·32배가 되는 시점을 시각화한 뒤 암산 도전 문제 4개를 푼다. 역사 자료의 1차 사료(1626.11.5 스카헨의 편지)와 비교 수치의 출처·개략치 여부를 활동 안에 명시한다.$ov$, now()),
  ($s$economics/mini/continuous_compound_lab$s$, $ov$연속복리를 세 탭으로 탐구하는 활동. ①주기를 쪼개 보기 — 원금 A, 연이율 r, 기간 n을 정하면 연·반기·분기·월·주·일·시간·분·초(m = 1, 2, 4, 12, 52.14, 365, 8760, 525600, 31536000)와 연속복리까지 각 주기의 원리합계 S_m = A(1+r/m)^(mn)이 계산되고, 선택한 주기의 계산식이 교과서와 같은 형태로 전개된다. ‘자동으로 쪼개 보기’를 누르면 주기가 차례로 짧아지며 값이 한계값에 다가가는 모습을 볼 수 있고, 연 1회 값에서 연속복리 값까지를 잘라 확대한 막대 그래프와 수렴 게이지, 직전 주기보다 늘어난 금액·실효 연이율 표로 ‘쪼갤수록 늘어나는 양이 급격히 줄어드는’ 현상을 관찰한다. 연 10%·100만원·1년이면 교과서와 같은 110, 110.38, 110.47, 110.52만원이 나오며, lim(1+r/m)^(m/r) = e에서 S = A·e^(rn)이 나오는 과정과 두 배가 되는 시간 ln2/r도 함께 다룬다. ②단리·복리·연속복리 — 같은 조건에서 A(1+rn), A(1+r)^n, A·e^(rn) 세 곡선을 한 그래프에 겹쳐 그리고 시점 슬라이더와 비교표로 언제나 단리 < 복리 < 연속복리이며 기간·이율이 커질수록 간격이 벌어짐을 확인한다(100만원 연 12% 30년이면 460 / 2,996 / 3,660만원). ③도전 문제 — 300만원을 연 5% 연속복리로 4년(e^0.2=1.22 → 366만원), 1,000만원을 연 5%로 10년간 단리·복리·연속복리(1.05^10=1.63, e^0.5=1.65 → 1,500 / 1,630 / 1,650만원), 교과서 표의 m별 값 채우기, 연속복리에서 두 배가 되는 시간(ln2/r) 네 문제를 단계별로 풀며 힌트·해설을 제공한다. 아주 큰 m에서도 오차가 없도록 log1p로 계산하며 이자소득세는 반영하지 않는다.$ov$, now()),
  ($s$economics/mini/installment_savings_lab$s$, $ov$정기 적금의 원리합계를 두 탭으로 탐구하는 활동. ①적금 시뮬레이터 — 매월(매년) 초 적립액 a, 이율 r, 기간 n을 정하면 교과서 그림과 같은 회차별 다이어그램(시간 축 위에 제1회부터 제n회까지의 화살표와 a(1+r)^(n−k+1) 라벨)이 그려지고, 화살표를 클릭하면 그 회차의 만기 금액과 이자가 붙는 기간이 표시되며 ‘회차별로 쌓아 보기’로 순서대로 나타나는 애니메이션도 볼 수 있다. 이어 첫째항 a(1+r)·공비 (1+r)·항수 n인 등비수열의 합으로 S = a(1+r){(1+r)^n − 1}/r 이 유도되는 과정을 대입식과 함께 보여 주고, 총 납입액·이자·원리합계, 넣은 돈과 원리합계를 겹쳐 그린 잔액 그래프(사이 영역이 이자), 회차별 만기 금액 표를 제공한다. ②단계별 문제 4개 — 매월 초 20만원씩 24개월 월이율 0.5%(1.005^24=1.127 → 5,105,400원), 매년 초 100만원씩 5년 연이율 4%(1.04^5=1.217 → 5,642,000원), 같은 총액·같은 연 4.8%에서 적금(3,890,500원·이자 290,500원)과 예금(4,143,600원·이자 543,600원)의 이자를 비교해 적금의 평균 예치 기간이 짧다는 점을 찾는 문제, 목표 금액에서 매월 적립액을 거꾸로 구하는 문제를 앞 단계를 맞혀야 다음이 열리는 방식으로 풀며, 문제를 푸는 동안 해당 조건의 회차별 다이어그램이 함께 표시된다. 기수불(매 기간 초 납입) 기준이며 문제에 주어진 거듭제곱 어림값과 세금 미반영을 활동 안에 명시한다.$ov$, now()),
  ($s$economics/mini/present_value_lab$s$, $ov$현재가치와 할인율을 세 탭으로 탐구하는 활동. ①현재 ⇄ 미래 왕복 시뮬레이터 — 현재가치·미래가치·할인율의 뜻을 카드로 정리한 뒤, 교과서 그림과 같은 다이어그램(왼쪽 현재가치 상자, 오른쪽 미래가치 상자, 위로 이자율 화살표, 아래로 할인율 화살표, 분홍 시간축)에서 방향(현재→미래 / 미래→현재)과 방법(단리/복리), 금액·이율·기간을 조작하면 S = A(1+rn)·A(1+r)^n 과 A = S/(1+rn)·S/(1+r)^n 이 단계별로 계산된다. ‘왕복 확인’ 버튼을 누르면 이자율로 곱했다가 같은 값의 할인율로 나누면 원래 금액으로 정확히 돌아옴을 보여 주고, 미래 1원의 현재가치(할인 계수)도 함께 제시한다. ②기간별 그래프 — 같은 r로 ‘지금 100만원이 n년 뒤 얼마가 되는가(미래가치, 위로 증가)’와 ‘n년 뒤 100만원이 지금 얼마인가(현재가치, 아래로 감소)’를 단리·복리 두 곡선으로 나란히 그려 곱하기와 나누기가 거울처럼 대칭임을 보이고, 할인율을 높이면 현재가치 곡선이 훨씬 가파르게 떨어짐을 관찰한다. ③단계별 문제 4개 — 연 4% 단리 10년 뒤 2,100만원의 현재가치(1,500만원)와 역방향 확인, 연 4% 복리 2년 만기 1,000만원의 현재가치(만원 미만 버림 924만원)와 단리 할인과의 비교, 100만원→105만원에서 이자율과 할인율이 같은 값임을 확인하기, 지금 500만원과 5년 뒤 700만원 중 유리한 쪽을 할인율 6%(현재가치 523.1만원)와 10%(434.6만원)에서 각각 판단해 할인율에 따라 결론이 뒤집힘을 체험하기. 문제에 주어진 어림값(1.06^5=1.3382, 1.1^5=1.61051)과 세금 미반영을 활동 안에 명시한다.$ov$, now()),
  ($s$economics/mini/pension_lab$s$, $ov$우리나라 연금 제도와 생명연금을 세 탭으로 탐구하는 활동. ①연금 3층 구조 카드 — 1층 공적연금(국민연금, 공무원·사학·군인연금), 2층 퇴직연금(DB형, DC형·IRP), 3층 개인연금(연금저축), 그리고 집을 연금으로 바꾸는 주택연금까지 6장의 카드를 누가 가입하는지·얼마를 내는지·언제 받는지·어떻게 계산되는지로 나누어 펼쳐 보고, 층을 누르면 해당 층만 골라 볼 수 있는 3층 집 인포그래픽을 제공한다. 국민연금 보험료율 9%(2025년 개정으로 2026년부터 단계적 인상, 2033년 13%)·수급 개시 만 65세(1969년생 이후)·노령연금 평균 월 약 65만원, 법정 퇴직급여 1년당 30일분 평균임금, 퇴직연금 적립금 약 430조원(2024년 말), 연금저축 세액공제 연 600만원·16.5%, 주택연금 만 55세·공시가격 12억원 이하 등 실제 제도와 수치를 근거와 함께 담았다. ②종신연금 vs 확정연금 — 같은 목돈을 연금으로 바꿀 때 기말 지급 연금식 m = P·i/{1−(1+i)^(−n)}으로 종신형(통계청 2023년 생명표의 기대여명 기준)과 확정기간형(5~30년)의 월 수령액을 계산하고, 사망 나이를 슬라이더로 바꾸며 총 수령액과 손익분기 나이(종신 총액이 확정 총액을 넘어서는 나이)를 타임라인으로 비교한다. 확정연금은 사망해도 남은 기간을 유족이 이어받는다는 점, 종신연금은 장수 위험에 대비하는 보험이라는 점을 표로 정리한다. ③실제 사례 계산 4문제 — 국민연금 보험료(월 300만원의 9%와 본인 부담 4.5%), 퇴직급여(평균임금 400만원×8년), 연금저축 세액공제(600만원×16.5%=99만원과 실질 수익률 19.8%), 확정연금의 현재가치(매년 말 1,200만원씩 10년, 할인율 4% → 약 9,733만원, 등비수열의 합)를 단계별로 푼다. 통계 수치는 개략치이며 기준 시점과 출처를 활동 안에 표기한다.$ov$, now()),
  ($s$economics/mini/budget_life_lab$s$, $ov$교과서의 ‘수입과 지출을 고려한 금융 생활’ 활동을 그대로 옮긴 세 탭 활동. ①A씨의 가계부 — 월수입 250만원인 A씨의 15개 지출 항목(주거비 50만·식비 40만·교통비 7만·의류 10만·통신 6만·소득세 27만·전기 4만·수도 2만·도서 5만·영화 3만·OTT 2만·대인관계 9만·의료 5만·자기계발 10만·저축 70만)을 비중 막대와 항목 카드로 보여 주고, 고정 지출과 자동 계산 항목을 구분한다. ②나의 조정 지출 — 조정1(수입 그대로 250만원), 조정2(20% 증가 300만원), 조정3(20% 감소 200만원) 세 시나리오를 오가며 항목별 슬라이더로 최소 비용을 조정하고, 보험료·개인연금·비상금·부모님 용돈·반려동물·운동·여행·커피 같은 항목을 직접 추가할 수 있다. 소득세는 교과서가 준 세율표(연 소득 1,400만원 초과 5,000만원 이하 = 84만원 + 초과분의 15%)로 자동 계산되어 250만원이면 27만원, 300만원이면 34.5만원, 200만원이면 19.5만원이 되고, 저축은 수입에서 지출을 뺀 나머지로 자동 계산되어 적자면 경고가 뜬다. A씨와 세 시나리오를 나란히 놓은 비교표와, 수입이 늘 때와 줄 때 차이가 가장 큰 항목 TOP3를 자동으로 뽑아 교과서의 (2)번 발문을 다룬다. ③저축이 만드는 10년 뒤 — 각 시나리오에서 정한 저축액을 매월 초 월이율 0.5% 복리로 120개월 적립할 때의 원리합계를 S = a(1+r){(1+r)^n−1}/r 로 계산해 납입액과 이자를 나눠 막대로 비교하고, 교과서 어림값 1.005^120 = 1.82(배수 164.82)와 정확한 값(164.70)을 전환해 볼 수 있으며, 매달 10만원을 더 저축하면 10년 뒤 약 1,648만원이 더 커진다는 것을 보여 준다. 소득세는 교과서 방식대로 연소득에 세율표를 바로 적용한 값이라 실제 근로소득세(각종 공제·4대 보험 반영)와는 다르다는 점을 명시한다.$ov$, now()),
  ($s$economics/mini/production_function_lab$s$, $ov$생산함수 Q = f(L, K) 를 세 탭으로 탐구하는 활동. ①두 변수를 함께 움직이기 — 곱셈형 Q = LK(교과서 예), 제곱근형 Q = √(2LK), 덧셈형 Q = 3L + 2K, 짝 맞추기형 Q = 4min(L, K) 네 가지 생산함수 중 하나를 고르고 노동량 L과 자본량 K를 0~5 범위에서 슬라이더로 조작하면, 인라인 SVG로 직접 그린 3차원 곡면(마우스·터치로 끌어서 회전, 기본·정면(L)·정면(K)·위에서 네 가지 시점 버튼) 위에서 현재 (L, K)의 높이가 빨간 점으로 표시되고 자본량을 묶은 초록 단면 곡선과 노동량을 묶은 파란 단면 곡선이 함께 그려지며, 대입 과정과 생산량 Q가 큰 숫자로 계산된다. 아래의 6×6 생산량 표는 (L, K) 한 쌍마다 Q가 하나씩 정해진다는 이변수함수의 뜻을 수치로 확인시켜 주고, 지금 고른 값에 가장 가까운 칸과 그 가로·세로 줄을 함께 강조해 표의 한 줄이 곧 단면임을 예고한다. 인적 자본·자연 자원 등 다른 생산 요소도 있으나 간단한 모델링을 위해 노동과 자본만 다룬다는 점을 함께 안내한다. ②하나를 고정하면 — 단면 — 노동량 L 또는 자본량 K를 고르고 고정값을 0.5 단위로 움직이면 3차원 곡면을 그 자리에서 자르는 반투명 평면과 잘린 자리에 남는 노란 단면 곡선이 나타나고, 그 옆에 같은 곡선이 2차원 좌표평면에 다시 그려지며 Q = K, Q = 2L, Q = √(4K) = 2√K, Q = 2K + 6 처럼 단면으로 얻어지는 일변수함수의 식과 그래프 모양 이름(원점을 지나는 직선·무리함수 곡선·기울기가 2인 직선·올라가다 평평해지는 꺾은선)이 자동으로 정리된다. 자유 변수 슬라이더로 곡선 위의 점을 움직이며 값을 읽고, 정수 여섯 개의 단면 값 표로 확인하며, 교과서 예시(Q = LK 에서 노동량이 1로 고정되면 Q = K, 자본량이 2로 고정되면 Q = 2L)를 버튼 한 번으로 재현해 볼 수 있다. ③단계별 문제 4개 — 곱셈형 Q = 3LK 에 대입하기와 한 요소만 2배(2배)·두 요소 모두 2배(4배)의 차이, 제곱근형 Q = √(8LK) 에서 자본량을 2로 고정해 Q = √(16L) = 4√L 을 얻고 값을 구하고 그래프 모양을 그림으로 고르고 역으로 노동량 구하기(L = 25), 일차형 Q = 25L 에서 목표 생산량에 필요한 노동량 되돌아 구하기(30,000 → 1,200 / 45,000 → 600만큼 더), Q = a√K 에서 조건으로 상수 정하기(K = 9일 때 Q = 480 → a = 160, K = 25 → 800, Q = 1,600 → K = 100)와 자본을 4배 늘려도 생산량은 2배뿐인 수확 체감 확인. 앞 단계를 맞혀야 다음이 열리며 힌트·정답 보기·해설을 제공하고, 그래프 모양 문제는 직선·무리함수·이차·반비례 썸네일 중에서 고른다.$ov$, now()),
  ($s$economics/mini/cost_function_lab$s$, $ov$비용함수 C = f(Q) 를 네 탭으로 탐구하는 활동. ①우리 가게 비용 시뮬레이터 — 버블티 가게·피자 푸드트럭·티셔츠 공방·독립출판 네 사례에서 고정 비용 항목(매장 월세·기계 리스료·화재 보험료·표지 디자인비 등)과 1개당 가변 비용 항목(재료·포장·수수료·인쇄비 등)을 각각 슬라이더로 직접 조작하면 총비용 그래프에서 고정 비용은 아래쪽 가로 띠로, 가변 비용은 그 위에 쌓이는 삼각형 영역으로 색이 나뉘어 총비용 = 고정 비용 + 가변 비용을 눈으로 확인한다. 생산량 슬라이더로 현재 점을 움직이며 고정 비용·가변 비용·총비용·1개당 비용을 함께 읽고, ‘1개당 비용’ 보기로 바꾸면 평균비용 C/Q = F/Q + v 곡선이 1개당 가변 비용을 점근선으로 삼아 내려가는 모습을 관찰해 많이 만들수록 한 개 값이 싸지는 까닭(고정 비용을 여러 개가 나눠 진다)을 체험한다. 금액은 비용 구조 이해를 위한 예시 값임을 명시한다. ②비용의 두 얼굴 — 임대료·기계 설비 구입비·화재 보험료·간판 제작비·정규직 기본급 등 고정 비용 7개와 재료 구입비·포장 상자·연료비·아르바이트 임금·택배비·잉크·카드 수수료 등 가변 비용 7개, 모두 14개 항목을 두 갈래로 분류하는 게임(항목마다 까닭 해설, 진행 막대, 다시 하기)과, 고정 비용을 바꾸면 그래프가 위아래로 평행이동하고 1개당 가변 비용을 바꾸면 기울기가 달라진다는 것을 기준선과 겹쳐 보며 확인하는 실험(3문항 즉답 퀴즈 포함), 그리고 소형·중형·대형 세 설비의 비용 직선을 한 좌표평면에 겹쳐 그려 생산량 50개와 100개에서 가장 싼 설비가 바뀌고 장기 비용은 늘 세 직선의 가장 아래(하단 포락선)를 따라간다는 것을 보이며 단기(고정 비용을 일정하게 취급)와 장기(모든 요소를 가변 비용으로 취급)의 차이를 다룬다. ③노동함수로 비용함수 만들기 — 크루아상 공방(Q = 10L), 가죽가방 공방(Q = 5√L), 명함 인쇄소(Q = 50L) 세 사례에서 생산함수 → 노동함수 L(Q)(역함수) → 가변 비용 R × L(Q) → 비용함수 C = F + R × L(Q) 로 이어지는 네 걸음을 카드로 보여 주고, 고정 비용 F와 노동 1단위당 임금 R을 조작하면 노동함수 그래프와 비용함수 그래프가 함께 다시 그려지며 필요한 노동량·가변 비용·고정 비용·총비용·1개당 비용이 계산된다. 생산함수가 일차함수면 비용함수도 일차함수, 무리함수면 비용함수는 이차함수가 됨을 두 그래프의 모양으로 확인한다. ④단계별 문제 4개 — 텀블러 공방(고정 150만원·1개당 8,000원: 비용함수 고르기, 250개의 가변 비용 200만원·총비용 350만원·1개당 14,000원, 예산 590만원이면 550개), 캔들 공방(고정 240만원·30개에 가변 45만원 비례: 1개당 15,000원 → 80개면 가변 120만원·총 360만원·1개당 45,000원), 고정 600·임금 5·Q = 8L(노동함수 Q/8 → C = 600 + (5/8)Q → Q = 240이면 750 → C = 1,000이면 Q = 640), 고정 250·임금 4·Q = 5√L(노동함수 Q²/25 → C = 250 + (4/25)Q² → Q = 50이면 650 → 생산량 2배면 가변 비용 4배)을 앞 단계를 맞혀야 다음이 열리는 방식으로 풀며 힌트·정답 보기·해설을 제공한다.$ov$, now()),
  ($s$economics/mini/demand_supply_lab$s$, $ov$수요함수와 공급함수를 네 탭으로 탐구하는 활동. ①수요함수 — 수요와 수요량의 뜻을 카드로 구분한 뒤, 영화 티켓(Qd = -40x + 600), 버블티(Qd = -25x + 200), 운동화(Qd = 600/x, 반비례), 수제 초콜릿(Qd = -2x² + 200) 네 사례 중 하나를 골라 가격 슬라이더를 움직이면 인라인 SVG 수요곡선 위의 점이 따라 움직이고 대입 과정과 수요량이 계산된다. ‘값 올리기·내리기’ 버튼을 누르면 가격이 얼마 오를 때 수요량이 얼마나 줄었는지 화살표와 함께 표시되어 수요의 법칙(우하향)을 직접 확인하고, 가격에 따른 수요량 표로 값의 변화를 수치로 읽는다. ②공급함수 — 같은 구성으로 크루아상(Qs = 30x - 60), 청바지(Qs = 250x, 정비례), 다육식물(Qs = 80√x), 원두(Qs = 2x²) 네 사례를 다루며 공급의 법칙(우상향)을 확인한다. 크루아상은 가격이 2천 원보다 싸면 공급량이 0이 되는 x절편의 뜻도 함께 짚는다. ③경제학은 왜 뒤집어 그릴까 — 수학은 가격을 x축·수량을 y축에 놓지만 경제학은 가격을 y축·수량을 x축에 놓는다는 관습(경제학자 Alfred Marshall의 영향)을 다룬다. 같은 그래프가 대각선 y = x를 기준으로 서서히 접히며 축 이름과 눈금이 크로스페이드로 뒤바뀌는 모핑 그래프를 슬라이더나 ‘뒤집기’ 버튼으로 조작할 수 있고, 빨간 점이 가리키는 (가격, 수량)이 두 그림에서 같은 값임을 확인한다. 축을 맞바꾸는 것이 곧 역함수의 그래프임을 수요함수의 식과 그것을 가격에 대해 푼 식(예: Qd = -40x + 600 ↔ x = (600 - Qd)/40, Qd = 600/x ↔ x = 600/Qd, Qs = 80√x ↔ x = (Qs/80)²)을 나란히 놓아 보이고, 축을 바꿔도 가격과 수량의 관계 자체는 그대로라 수요곡선은 늘 우하향, 공급곡선은 늘 우상향임을 4문항 퀴즈로 정리한다. ④단계별 문제 4개 — 반비례 수요함수 Qd = 720/x(3만원이면 240개, 6만원이면 120개, 가격이 2배면 수요량은 절반, 수요량 90개면 8만원), 표의 두 점(4만원 36개·10만원 18개)에서 Qd = ax + b의 a = -3·b = 48을 구하고 12만원일 때 12개·수요량 0이 되는 가격 16만원 찾기, 정비례 공급함수 Qs = 300x (5만원이면 1,500개, 7만원이면 2,100개, 2,400개면 8만원, 그래프 모양 고르기), 표의 두 점(6만원 20개·14만원 60개)에서 Qs = ax + b의 a = 5·b = -10을 구하고 20만원일 때 90개·공급을 시작하는 최저 가격 2만원 찾기를 앞 단계를 맞혀야 다음이 열리는 방식으로 풀며 힌트·정답 보기·해설을 제공한다.$ov$, now()),
  ($s$economics/mini/demand_forecast_lab$s$, $ov$가격에 따른 수요량을 예측하는 방법을 세 탭으로 탐구하는 활동. ①두 점으로 수요곡선 찾기 — 수요곡선이 직선이면 두 점의 좌표만으로 방정식을 정할 수 있다는 것을, 좌표평면 위의 점 A와 B를 마우스·터치로 직접 끌어(0.5 단위 스냅) 옮기며 확인한다. 점을 옮길 때마다 기울기 a = (y₂-y₁)/(x₂-x₁) 와 y절편 b = y₁ - a·x₁ 의 계산 과정이 값과 함께 다시 쓰이고 수요함수 Qd = ax + b 가 완성되며, 직선은 격자 안쪽만 clip 되어 그려진다. 주스·팝콘·양말·이어폰 네 가지 시작 자료를 고를 수 있고, 기울기가 음수가 아니게 되면 수요곡선보다 공급곡선에 가깝다는 안내가 뜬다. 예측 지점 슬라이더로 임의의 가격에서의 수요량을 읽고, 가격 1~6에 대한 예측 표는 값을 바로 보거나 ‘가리고 직접 채우기’로 바꿔 학생이 입력한 뒤 채점할 수 있다. ②최소제곱법으로 예측하기 — 조사한 값들이 한 직선 위에 정확히 놓이지 않는 컵케이크 가게 자료(가격 1·2·3천원에 실제 수요량 79·73·71개, 수요함수는 Qd = ax + 80 꼴)로 최소제곱법을 다룬다. 상수 a 슬라이더를 움직이면 산점도 위의 예측 직선이 함께 움직이고, 점마다 (예측 - 실제) 를 한 변으로 하는 붉은 정사각형이 그려져 ‘차의 제곱’이 곧 넓이임을 눈으로 보여 주며, 그 넓이의 합 C 가 큰 숫자와 잔차 표(가격·실제·예측·차·차²·합계)로 함께 계산된다. 아래의 두 번째 그래프는 a에 대한 이차함수 C(a) 의 포물선으로, 현재 a의 위치와 꼭짓점을 표시해 최솟값을 눈으로 찾게 하고 ‘가장 작아지는 곳으로’ 버튼으로 애니메이션 이동한다. C = (a+1)² + (2a+7)² + (3a+9)² = 14a² + 84a + 131 = 14(a+3)² + 5 로 정리되는 과정을 보여 주고, a = -3 일 때 C = 5 로 최소가 되므로 수요함수를 Qd = -3x + 80 으로 판단해 가격 5천원일 때의 수요량 65개를 예측한다. ③단계별 문제 3개 — 두 자료(가격 3에 24, 가격 7에 12)로 Qd = -3x + 33 을 구하고 가격 5의 수요량 18과 수요량이 0이 되는 가격 11 찾기, Qd = ax + 60 꼴과 실제 자료(가격 1·2·4에 58·51·44)로 C = 21a² + 168a + 341 = 21(a+4)² + 5 를 완성해 a = -4 를 얻고 가격 3의 수요량 48 예측하기, 두 자료(가격 2에 90, 가격 6에 66)로 Qd = -6x + 102 를 구한 뒤 가격 20을 넣으면 수요량이 -18 이 나오는 것을 보고 조사 범위를 크게 벗어난 예측은 믿기 어렵다는 점을 판단하기. 앞 단계를 맞혀야 다음이 열리며 힌트·정답 보기·해설을 제공한다.$ov$, now()),
  ($s$economics/mini/utility_function_lab$s$, $ov$효용함수를 네 탭으로 탐구하는 활동. ①효용과 효용함수 — 효용은 소비할 때 얻는 주관적인 만족도이고 사람마다 다르다는 점을 카드로 정리한 뒤, 피자(U = -0.5x² + 5x), 영화(U = 4√x), 최애 노래(U = 2x), 매운 떡볶이(U = -x² + 4x) 네 사례 중 하나를 골라 소비량 슬라이더를 움직이면 인라인 SVG 곡선 위의 점과 대입식, 효용 값이 함께 계산된다. 이차형은 꼭짓점(최대 효용)을 표시하고 효용이 음수가 되면 먹지 않느니만 못하다는 안내가 뜨며, 정수 소비량별 효용 표도 함께 제공한다. ②한계효용 체감의 법칙 — MU(n) = U(n) - U(n-1) 을 정의한 뒤 ‘한 개 더!’ 버튼을 누를 때마다 소비량이 하나씩 늘어나고, 총효용 막대그래프와 한계효용 막대그래프가 차례로 채워져 늘어나는 폭이 점점 작아지는 모습을 눈으로 확인한다. 다음 한 개의 한계효용이 양수·0·음수인지에 따라 안내 문구와 색이 바뀜고(0일 때 총효용이 최대, 음수면 그만 먹을 것), n·U·MU 세 줄 표와 네 사례의 한계효용 수열을 나란히 비교해 체감형과 불변형(최애 노래)을 구분한다. ③나의 효용 곡선 그리기 — 딸기·초콜릿·탄산음료·라면 중 하나를 고르고 좌표평면을 눌러(끌어) 1~6개에서의 만족도를 0.5 단위로 직접 찍으면 점이 선으로 이어져 나만의 효용 곡선이 만들어진다. 표에 효용과 한계효용이 채워지고, 모두 찍으면 내 곡선이 한계효용 체감을 따르는지 자동으로 판정해 준다. 체감형과 비례형인 친구 두 명의 곡선을 겹쳐 같은 상품이라도 사람마다 곡선의 모양이 다르다는 주관성을 확인한다. ④단계별 문제 4개 — 무리함수 꼴 U = √(8x)(x = 2면 4, x = 8이면 8, 소비량이 4배면 효용은 2배, U = 12면 x = 18), 이차함수 꼴 U = -x² + 12x(x = 4면 32, 최대가 되는 x = 6과 그때의 36, U = 0이 되는 x = 12), 표에서 한계효용 읽기(사탕 0~5개의 효용 0·6·10·13·15·16 → 세 번째의 한계효용 3, 한계효용의 합 16이 총효용과 같음, 체감 판단, 한계효용이 0이면 총효용 16 유지), 같은 상품에 대한 두 사람의 효용함수 비교(6√x ↔ 3x: x = 1이면 6과 3, x = 4면 둘 다 12, x = 9면 18과 27 → 효용은 주관적인 지표)를 앞 단계를 맞혀야 다음이 열리는 방식으로 풀며 힌트·정답 보기·해설을 제공한다.$ov$, now()),
  ($s$economics/mini/ordinal_cardinal_lab$s$, $ov$서수적 효용함수와 기수적 효용함수를 네 탭으로 탐구하는 활동. ①순서만? 크기까지? — 만족도의 순서는 알 수 있으나 크기는 알 수 없는 서수적 효용함수와, 순서와 크기를 모두 알 수 있는 기수적 효용함수를 말풍선 예시와 함께 구분하고, 도넛·주스·라면 세 사례에서 소비량 1~5의 효용의 크기가 주어졌을 때 선호도 순위 칸을 눌러 채우고(누를 때마다 1위→2위→… 로 순환하며 한 칸은 미리 채워져 있음) 채점한다. 모두 맞히면 메달과 함께 기수적 정보에서 서수적 정보는 언제나 뽑아낼 수 있다는 점을 정리하고, 반대로 순위만 알면 크기도 알 수 있을지 확인하는 버튼을 누르면 순위는 똑같지만 점수는 제각각인 세 사람의 표가 나타나 서수적 효용함수만으로는 크기를 알 수 없음을 보여 준다. ②값을 바꿔도 순위는 그대로? — 효용 값에 V = U, 2U, U + 10, U², √U, -U, 20 - U 일곱 가지 변환을 켜고 끄며 값과 순위 수열을 표로 비교하고, 값의 범위가 서로 달라도 견줄 수 있게 같은 높이로 정규화해 겹쳐 그린 그래프로 확인한다. U가 커질 때 함께 커지는 변환은 순위를 바꾸지 않아 초록으로, 값을 거꾸로 만드는 변환은 순위를 뒤집어 붉은 점선으로 표시되며, 같은 선호를 나타내는 서수적 효용함수가 무수히 많다는 점을 알 수 있다. ③순서만으로 답할 수 있을까 — ‘세 개와 다섯 개 중 어느 쪽이 더 만족스러운가’, ‘몇 배 더 만족스러운가’, ‘네 번째 한 개의 한계효용은 얼마인가’, ‘가장 만족스러운 소비량은’ 등 10개 질문을 순서만으로 OK(서수적)인지 크기까지 필요(기수적)한지 분류하는 게임. 항목마다 까닭 해설과 진행 막대가 있고, 모두 맞히면 소비자 이론에서는 서수적 효용함수만으로도 충분한 정보 도출이 가능하다는 마무리가 나타난다. ④단계별 문제 4개 — 효용의 크기 5·11·8·14·12 에서 순위 뽑기(1위는 x = 4, x = 2는 3위, 4위는 x = 3, 순위만 남으면 답할 수 없게 되는 질문 고르기), 말풍선을 보고 서수적인지 기수적인지 판단하기, 효용 2·5·9·6·3 에 V = 3U + 1 을 적용해 x = 3 에서 V = 28 을 구하고 U와 V의 1위가 모두 x = 3 임을 확인한 뒤 그 까닭 고르기, 효용 4·9·12·13 에서 한계효용 5·3·1 을 구하고 순위만으로는 이 계산을 할 수 없음을 판단하기. 앞 단계를 맞혀야 다음이 열리며 힌트·정답 보기·해설을 제공한다.$ov$, now()),
  ($s$economics/mini/equilibrium_price_lab$s$, $ov$균형가격이 정해지는 과정과 수요·공급의 변화를 세 탭으로 탐구하는 활동. ①균형점 찾기 — 수요의 법칙(우하향)과 공급의 법칙(우상향)을 짚은 뒤 무선 이어폰(Qd = -2x + 240, Qs = 4x), 캡모자(Qd = -4x + 200, Qs = 8x - 40), 화분(Qd = -3x + 120, Qs = x + 8) 세 시장 중 하나를 골라 가격 슬라이더로 직접 값을 매겨 본다. 인라인 SVG 그래프(가로축 가격, 세로축 수량 — 교과서와 같은 방식)에 두 곡선과 균형점이 그려지고, 지금 매긴 가격에서 수요량과 공급량의 차이가 굵은 세로 막대로 나타난다. 값이 비싸면 초과공급(안 팔린 재고 상자 그림과 함께 값을 내리게 된다는 안내), 싸면 초과수요(못 산 사람 그림과 함께 값이 오르게 된다는 안내), 딱 맞으면 균형 표시가 뜬다. ‘시장에 맡겨 보기’ 버튼을 누르면 가격이 균형으로 미끄러지듯 옮겨 가고, f(x) = g(x) 를 푸는 과정과 가격별 수요량·공급량·차이 표가 함께 제공된다. 캡모자는 공급함수의 x절편(5천 원)보다 싸면 공급량이 0이 되는 것도 다룬다. ②점이 움직일까, 곡선이 움직일까 — 수요량의 변화(같은 곡선 위에서 점이 이동)와 수요의 변화(가격 이외의 요인으로 곡선 자체가 이동)를 구분한다. 먼저 아이스크림 수요곡선 하나만 두고 손잡이 두 개를 돌려 보는데, 가격 손잡이를 돌리면 곡선은 그대로인 채 점만 미끄러지며 ‘수요량의 변화’ 배지가, 날씨·유행·소득 같은 가격 밖 손잡이를 돌리면 원래 곡선을 점선으로 남긴 채 곡선 자체가 평행이동하며 ‘수요의 변화’ 배지가 뜬다. 이어 아이스크림 가게에 일어난 실생활 사건 8가지(폭염, 값 인상을 사는 쪽에서 볼 때와 만드는 쪽에서 볼 때, 옆 가게 빙수 반값, 원유 값 폭등, 새 공장 준공, 인기 드라마 등장, 물류비 지원)를 카드로 고르고 ‘점이 이동할까 곡선이 이동할까’, ‘어느 쪽으로 움직일까(또는 그 양이 늘까 줄까)’ 두 단계로 답한다. 맞히면 그래프가 실제로 그렇게 움직이며 균형가격과 균형거래량이 어떻게 옮겨 가는지(수요 증가 → 20에서 23, 100에서 130 처럼) 화살표와 함께 보여 준다. 같은 가격 인상이라도 사는 쪽에서는 수요량이 줄고 만드는 쪽에서는 공급량이 는다는 대비가 한 쌍으로 들어 있다. ③단계별 문제 4개 — 프린터(Qd = -3x + 480, Qs = 5x)의 균형 조건 식 고르기와 균형가격 60만 원·균형거래량 300대, 가격 80만 원일 때의 초과공급 160대, 의자(Qd = -4x + 300, Qs = 2x - 60)의 균형가격 60만 원·균형거래량 60개와 공급을 시작하는 최저 가격 30만 원, 가격 45만 원일 때의 초과수요 90개, 초콜릿 이야기로 수요량의 변화와 수요의 변화·공급의 감소를 판별하고 수요가 늘 때 균형가격과 균형거래량이 모두 오른다는 것 고르기, 우산(Qd = -2x + 200, Qs = 2x)에서 모든 가격의 수요량이 60개 늘었을 때 새 수요함수 Qd = -2x + 260 을 고르고 균형가격이 50에서 65 천 원으로, 균형거래량이 100에서 130개로 커지는 것 구하기. 앞 단계를 맞혀야 다음이 열리며 힌트·정답 보기·해설을 제공한다.$ov$, now()),
  ($s$economics/mini/market_adjust_lab$s$, $ov$시장가격이 균형가격과 다를 때 어떤 일이 벌어지고 어떻게 균형을 찾아가는지 세 탭으로 탐구하는 활동. ①남을까, 모자랄까 — (시장가격) > (균형가격)이면 초과 공급, (시장가격) < (균형가격)이면 초과 수요가 생긴다는 것을 카드로 짚고, 콘서트 티켓(Qd = -20x + 1400, Qs = 30x - 100), 딸기(Qd = -30x + 900, Qs = 20x - 100), 게임기(Qd = -5x + 700, Qs = 15x - 300), 자전거(Qd = -8x + 640, Qs = 12x - 160) 네 시장 중 하나를 골라 시장가격 슬라이더를 움직인다. 인라인 SVG 그래프(가로축 가격, 세로축 수량)에 균형점과 시장가격 세로선이 그려지고, 그 가격에서의 수요량과 공급량 사이를 잇는 양방향 화살표에 ‘초과 공급량’ 또는 ‘초과 수요량’ 말풍선이 붙어 교과서 그림을 그대로 재현한다. 빈 좌석·안 팔린 팩·창고 재고처럼 시장마다 다른 말로 남거나 모자란 양을 알려 주고, 초과량이 (두 기울기의 차이) × (균형가격에서 떨어진 거리)로 계산된다는 것도 함께 보여 준다. 이어 완판·웃돈·예약 대기·품귀와 재고·떨이·폐기·폭락이 담긴 실제 같은 뉴스 헤드라인 8개를 읽고 초과 공급인지 초과 수요인지 맞히는 게임을 한다. ②균형을 찾아가는 여정 — 균형보다 비싸게 또는 싸게 시작해 ‘하루 지나기’ 버튼을 누르면, 남거나 모자란 양에 비례해 값이 움직이며 하루씩 균형에 다가간다. ‘끝까지’ 버튼으로 자동 재생할 수도 있다. 교과서의 흐름도(초과 공급 발생 → 잉여 물품 발생 → 물건을 팔기 위해 가격 하락 → 균형점 도달, 초과 수요일 때는 초과 수요 발생 → 시장의 물품 부족 → 희귀성으로 가격 상승 → 균형점 도달)가 네 단계 배지로 나타나 지금 어디쯤인지 알려 주고, 그래프에는 지나온 가격의 자취가, 아래에는 날짜에 따른 시장가격 변화 그래프가 균형가격 점선과 함께 그려진다. 날마다 사려는 양·팔려는 양·남거나 모자란 양과 값이 오르내린 폭이 기록되는 일지가 쌓이고, 균형에 이르면 값을 바꿀 까닭이 없어져 균형가격과 균형거래량이 유지된다는 것을 확인한다. 처음에는 값이 크게 움직이다가 균형에 가까워질수록 조금씩만 움직이는 모습도 관찰할 수 있다. ③단계별 문제 4개 — 헤드폰(Qd = -12x + 480, Qs = 8x - 20)의 균형가격 25만 원과 시장가격 30만 원에서의 수요량 120개·공급량 220개·초과 공급량 100개, 그리고 앞으로 값이 내려간다는 판단, 귤(Qd = -25x + 750, Qs = 25x - 250)의 균형가격 20천 원과 시장가격 14천 원에서의 초과 수요량 300상자·품귀와 가격 상승·균형거래량 250상자, 가방(Qd = -6x + 480, Qs = 9x - 120)에서 균형가격 40만 원을 구한 뒤 50만 원일 때의 초과 공급량과 30만 원일 때의 초과 수요량이 모두 150개로 같은 까닭 찾기, 뉴스 헤드라인으로 시장가격과 균형가격의 대소를 판단하고 초과 공급일 때 값이 내려간다는 것과 균형에 이르면 균형가격·균형거래량이 유지된다는 것 고르기. 앞 단계를 맞혀야 다음이 열리며 힌트·정답 보기·해설을 제공한다.$ov$, now()),
  ($s$economics/mini/equilibrium_change_lab$s$, $ov$외부 환경의 변화로 균형가격과 균형거래량이 달라지는 현상을 다섯 탭으로 탐구하는 활동. ①세금과 균형점 — 휘발유(Qd = -x + 300, Qs = 3x - 100), 탄산음료(Qd = -2x + 360, Qs = 2x - 40), 자동차(Qd = -3x + 400, Qs = x + 100) 세 시장에서 1개당 세금 슬라이더를 움직이면 공급곡선이 옮겨 가고 균형점이 E₀에서 E₁으로 이동한다. 세금 증가 → 생산 비용 증가 효과 → 균형점 이동 → 균형가격 상승·균형거래량 감소 라는 수업 자료의 흐름도가 단계 배지로 나타나고, 세금을 줄이면 반대 흐름이 나타난다. 그래프에는 수업 자료 그림처럼 소비자 부담(노랑)과 공급자 부담(자홍) 직사각형, 그리고 세금으로 인한 사회적 손실(파랑) 삼각형이 색으로 칠해지며, 생산자가 실제로 받는 값과 소비자가 내는 값이 함께 표시된다. 부담 비율 막대로 소비자와 공급자가 세금을 몇 대 몇으로 나누어 지는지 보여 주는데, 세 시장의 비율이 각각 75:25, 50:50, 25:75 로 설계되어 값에 덜 민감한 쪽이 더 많이 부담한다는 탄력성 이야기를 한눈에 견줄 수 있다. 정부가 걷는 세금과 사회적 손실도 함께 계산되어, 세금 부과가 마냥 좋은 구매 억제 정책은 아니라는 점을 짚는다. ②소득과 균형점 — 해외여행 상품·디저트 카페(정상재)와 봉지 라면(열등재) 가운데 하나를 골라 소득 슬라이더를 움직이면 수요곡선이 옮겨 가고 균형점이 이동한다. 소득 증가 → 구매력 증가 효과 → 균형점 이동 → 균형가격 상승·균형거래량 증가 흐름도가 나타나며, 열등재에서는 소득이 늘 때 오히려 수요가 줄어 결과가 뒤집히는 것을 확인한다. ③수요를 움직이는 것들 — 소득, 기호와 유행, 대체재·보완재 가격, 수요자의 수, 미래 가격 기대 등 여덟 가지 실생활 사건(폭염과 아이스크림, 빙수 반값, 국민 소득 증가, 신제품 출시 소문, 신생아 수 감소, 새 학기, 휘발유 값 급등과 자동차, 드라마 PPL)을 카드로 고르고 수요가 늘지 줄지, 그 결과 균형가격과 균형거래량이 어떻게 되는지 두 단계로 답한다. 맞히면 그래프가 실제로 움직이며 균형이 (80, 140)에서 어디로 옮겨 가는지 보여 주고 요인의 종류를 알려 준다. ④공급을 움직이는 것들 — 원자재 가격, 생산 기술, 생산자의 수, 세금과 보조금, 자연재해 등 여덟 가지 사건(밀가루 값 폭등, 자동화 설비, 태풍 피해, 새 공장 준공, 정부 보조금, 개별소비세 인상, 국제 유가 급등, 역대급 풍년)을 같은 방식으로 다룬다. 모두 해결하면 수요 증가는 가격↑ 거래량↑, 수요 감소는 가격↓ 거래량↓, 공급 증가는 가격↓ 거래량↑, 공급 감소는 가격↑ 거래량↓ 라는 네 가지 결론이 정리된다. ⑤단계별 문제 4개 — 모니터(수요함수 그대로, 공급함수가 2x + 100 에서 2x - 50 으로)의 세금 전후 균형가격 100과 130, 균형거래량이 90대 줄어드는 것과 세금 증가의 결과 고르기, 무선 스피커(공급함수가 x + 300 에서 x + 210 으로)의 균형가격 200과 230, 소비자가 1개당 추가로 부담하는 30과 1개당 세금 90 가운데 공급자 부담 60 구하기, 캠핑용품(공급함수 그대로, 수요함수가 -x + 320 에서 -x + 400 으로)의 작년·올해 균형가격 120·160과 균형거래량 200·240, 그리고 원자재 값 상승·새 기술·대체재 가격 하락·세금 부담의 귀착을 판단하는 종합 문제. 앞 단계를 맞혀야 다음이 열리며 힌트·정답 보기·해설을 제공한다.$ov$, now()),
  ($s$economics/mini/tax_explorer_lab$s$, $ov$공학도구를 쓰듯 함수의 계수를 손잡이로 바꿔 가며 균형점을 찾는 활동. 네 탭으로 이루어져 있다. ①공학도구 실험실 — 수요함수 f(x) = dA·x + dB 와 공급함수 g(x) = sA·x + sB 의 기울기와 절편을 각각 슬라이더로 조작하면 그래프가 곧바로 다시 그려지고 두 곡선의 교점(균형가격, 균형거래량)이 소수 둘째 자리까지 자동으로 계산된다. 세금 a 슬라이더를 움직이면 공급함수가 g(x) = sA(x − a) + sB 로 바뀌는 과정이 교과서와 같은 (x − a) 꼴과 정리한 꼴로 함께 표시되고, 원래 공급곡선은 점선으로 남아 얼마나 옮겨 갔는지 견줄 수 있다. 세금 1당 균형가격과 균형거래량이 얼마씩 달라지는지도 실시간으로 보여 준다. ‘균형점의 자취 보기’를 켜면 세금을 0에서 180까지 늘릴 때 균형점이 지나는 길이 굵게 표시되는데, 그 길이 바로 수요곡선 위라는 것을 눈으로 발견하게 된다(세금은 공급함수만 바꾸고 수요함수는 그대로이기 때문). 기본·공급이 민감한 시장·수요가 민감한 시장 세 가지 시작 설정을 제공하며, 세금이 지나치게 커서 거래가 이루어지지 않는 경우에는 안내 문구가 뜬다. ②표 채우기 — 수요함수 f(x) = -2x + 600, 공급함수 g(x) = x + 120 인 시장에서 세금을 0, 30, 60, 90 으로 바꿔 가며 수업 자료와 같은 표를 채운다. 공급함수는 세 보기 가운데 g(x) = (x − a) + 120 을 고르고 균형가격과 균형거래량은 직접 계산해 입력한 뒤 채점하며, 칸마다 ‘공학도구로 그래프 보기’ 버튼이 있어 자기 답을 그래프로 확인할 수 있다. 모두 맞히면 네 개의 균형점이 수요곡선 위에 나란히 놓인 그래프와 함께 세금이 30씩 늘 때 균형가격은 10씩 오르고 균형거래량은 20씩 준다는 규칙을 짚어 준다. ③규칙 찾기 — 완성된 표에 변화량 줄을 더해 보여 주고, 균형가격과 균형거래량을 세금 a의 식 x₀ = 160 + a/3, Q₀ = 280 − 2a/3 으로 나타내는 단계, 표에 없는 a = 150 에서의 값을 예측하는 단계, 거꾸로 균형거래량이 200이 되게 하는 세금 120을 구하는 단계, 균형점이 수요곡선을 따라 미끄러지는 까닭을 고르는 단계까지 여섯 단계로 이어진다. 마지막에는 세금 1당 균형가격의 변화가 공급 기울기 ÷ (공급 기울기 − 수요 기울기) 로 정해진다는 일반화를 세 시장의 값과 함께 제시하고, 공학도구 탭에서 직접 확인해 보도록 안내한다. ④단계별 문제 4개 — f(x) = -x + 480, g(x) = 3x + 40 에 세금 40을 부과할 때의 공급함수 고르기와 균형가격 110에서 140, 균형거래량 340 구하기, f(x) = -2x + 900, g(x) = 2x + 100 에서 세금 100일 때의 균형과 균형거래량이 350이 되게 하는 세금 150 및 세금 1당 균형가격 상승분 0.5 찾기, f(x) = -x + 400, g(x) = x + 100 에서 세금 50과 100일 때의 균형점이 모두 수요곡선 위에 있음을 확인하고 그 까닭 고르기, 수요 기울기가 다른 두 시장에 같은 세금 40을 부과해 균형가격이 각각 30과 10 오르는 것을 비교하고 수요가 값에 덜 민감한 쪽에서 세금이 가격에 더 많이 반영된다는 것 판단하기. 앞 단계를 맞혀야 다음이 열리며 힌트·정답 보기·해설을 제공한다.$ov$, now()),
  ($s$economics/mini/inflation_lab$s$, $ov$물가가 오르는 일(인플레이션)을 균형가격의 이동으로 풀어 보는 네 탭 활동. ①곡선을 움직여 보자 — 식빵 시장의 수요함수 f(x) = -2x + 1000, 공급함수 g(x) = 3x + 250(기준 균형 (150, 700))에서 수요곡선과 공급곡선을 -200 ~ +200까지 25씩 위아래로 옮기는 손잡이 두 개를 준다. 289가지 조합에서 균형이 늘 정수로 떨어지도록 계수를 맞추었고, 균형가격은 70~230, 균형거래량은 500~900 안에 머문다. 프리셋 네 개(평소 / 수요 증가 k=150 → (180, 790) / 생산비 상승 m=-150 → (180, 640) / 수요 감소·비용 상승 k=-100, m=-200 → (170, 560))로 물가가 오르는 두 길을 견주고, 수업 자료의 탐구를 다른 사례(무더위와 생수 · 원두값과 커피)로 바꾼 빈칸 채우기 두 문제(곡선의 이동 방향 · 균형가격 · 균형거래량)를 그래프와 이어 풀게 한다. 가로축이 가격이라 경제 책의 좌우 이동이 여기서는 위아래 이동으로 나타난다는 점을 따로 짚어 준다. ②무슨 일이 생겼을까 — 소비 지원금 · 국제 유가 상승 · 금리 인하 · 소비 위축 · 생산성 향상 · 밀 흉작 여섯 사건마다 어느 곡선이 어느 쪽으로 움직이는지, 균형가격과 균형거래량은 어떻게 되는지 네 가지를 먼저 예측하고 확인을 누르면 곡선이 실제로 미끄러지며 채점된다. 정답 분포는 수요/공급 3대 3, 위/아래 3대 3으로 골고루 섞었고, 맞히면 '수요가 끌어올린 물가 · 비용이 밀어올린 물가' 같은 유형 배지가 붙는다. ③내 돈의 힘 — 물가 상승률 0.5~12%와 1~20년 손잡이로 물가지수 100(1+r)^n 과 화폐가치 100/(1+r)^n 두 곡선을 함께 그리고, 김밥·영화표·버스 요금의 미래 가격과 1만원의 구매력 막대, 72의 법칙으로 어림한 물가 두 배 시점을 보여 준다. 단계별 문제 네 개(4,000원 김밥의 4년 뒤 값 4,862원 / 월급 3%·물가 6% 상승 시 실질 소득 약 2.8% 감소 / 72÷6 = 12년 / 100만원의 10년 뒤 실질 가치 약 68만원)로 마무리한다. ④역사 속 물가 — 인플레이션·디플레이션·스태그플레이션 세 유형 카드를 누르면 가로축 실질 경제성장률, 세로축 소비자물가 상승률의 사분면 그래프에서 해당 구역이 밝아진다. 우리나라 1998(-5.1, 7.5) · 2009(0.8, 2.8) · 2015(2.8, 0.7) · 2020(-0.7, 0.5) · 2022(2.7, 5.1) · 2024(2.0, 2.3)과 일본 1999(-0.3, -0.3) · 2009(-5.7, -1.4) · 2016(0.8, -0.1) 아홉 개 점을 눌러 그해의 이야기와 두 지표 막대를 확인하고, 특별한 세 장면(1922~1923년 독일의 빵값을 10배 눈금 막대로 그린 초인플레이션, 물가 28.7%에 성장률 -1.6%였던 1980년 우리나라, 물가가 오르지 않던 일본)과 여섯 문제 분류 퀴즈로 세 현상을 가른다. 통계 수치의 출처와 반올림 사실은 활동 끝에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/region_lab$s$, $ov$부등식 하나가 좌표평면을 두 쪽으로 가르는 일을 직접 그리고 판정해 보는 세 탭 활동. ①영역 그리기 — 직선 y ⊐ ax + b, 세로선 x ⊐ c, 원 x² + y² ⊐ r² 세 가지 꼴을 손잡이로 만들고 부등호 네 개(>, ≥, <, ≤)를 눌러 바꾼다. 등호가 들어가면 경계가 실선, 없으면 점선으로 저절로 바뀌고 '실선·경계 포함 / 점선·경계 제외' 배지가 함께 붙는다. 평면을 누르면 그 격자점이 영역에 들어가는지 좌표를 대입한 식과 함께 알려 주고(최대 여섯 점까지 남는다), 경계 위를 누르면 실선과 점선의 차이가 그대로 드러난다. 파란 점 셋만 영역에 넣고 빨간 점 둘은 밖에 두는 '점 가르기 미션' 세 개를 붙였는데, 차례로 가로선 · 세로선 · 원으로 풀리도록 점을 배치했다. ②어느 부분일까 — 부등식을 보고 네 개의 작은 좌표평면 그림 가운데 맞는 것을 고르는 일곱 문제. 보기 넷은 같은 경계선에 부등호만 네 가지로 바꾼 것이라 윗부분·아랫부분과 실선·점선을 함께 가려야 한다. 2x + y - 4 > 0, x - 3y + 6 ≤ 0 처럼 y가 정리되지 않은 꼴을 넣어 이항 연습을 하고, 특히 음수로 나눌 때 부등호의 방향이 뒤집히는 것을 짚는다. 가로선(y + 2 ≤ 0) · 세로선(x - 1 > 0) · 원(x² + y² < 9) 까지 다루며 정답 자리는 3, 1, 4, 2, 3, 1, 2 로 흩어 놓았고, 답을 고른 뒤에야 y에 대하여 정리한 꼴을 보여 준다. ③이 점, 들어갈까 — 부등식과 점 하나를 보여 주고 영역에 들어가는지 두 갈래로 답하는 열 문제. 답하기 전에는 경계선만 보이고 답한 뒤에 영역이 칠해지며, 대입한 식과 풀이가 함께 나온다. y < x + 2 와 y ≤ x + 2 에 같은 점 (1, 3)을 넣은 짝을 첫 두 문제로 두어 등호 하나가 답을 뒤집는 것을 보여 주고, x² + y² ≤ 25 에 (3, -4)처럼 경계에 딱 놓인 점을 넷 넣었다. 연속 정답은 불꽃 표시로 세어 준다. 연립부등식의 영역과 그것을 쓰는 선형계획법은 뒤의 다른 활동에서 다루므로, 이 활동은 부등식 하나가 만드는 영역을 읽고 그리는 데 집중한다.$ov$, now()),
  ($s$economics/mini/system_region_lab$s$, $ov$연립부등식의 영역을 만들고 그 위에서 일차식의 최대·최소를 찾는 네 탭 활동. 네 탭이 '영역 그리기 → 원리 → 꼭짓점 찾기 → 꼭짓점에 대입하기' 로 이어진다. ①하나씩 겹쳐 보기 — 세 개의 연립부등식 세트를 준다. 부등식마다 '어느 쪽 영역인가(위/아래 또는 좌/우)'와 '경계선은 실선인가 점선인가'를 고르면 그 반평면이 저마다 다른 색으로 좌표평면에 나타나고, 셋을 모두 풀면 겹치는 부분이 진하게 칠해지며 꼭짓점 좌표가 표시된다. x - y ≤ 2, x - y + 3 ≥ 0, x - y - 1 < 0 처럼 y가 정리되지 않은 꼴을 넣어 음수로 나눌 때 부등호가 뒤집히는 것을 연습하고, 세로선 x > -1 도 함께 다뤄 좌우로 갈리는 경우를 짚는다. 세 세트의 답은 각각 삼각형 (3,1)(-1,5)(-1,-3), (-3,0)(3,0)(1,4), (-2,3)(-2,-3)(4,3) 이다. ②직선을 밀어라 — x ≥ 0, y ≥ 0, x + 2y ≤ 8, 2x + y ≤ 10 이 만드는 사각형 영역(꼭짓점 (0,0), (5,0), (4,2), (0,4))에서 일차식 x + y, 3x + y, y - x, x + 3y 를 골라 f(x, y) = k 직선을 k 손잡이로 밀어 본다. 직선이 영역과 만나면 노란색, 벗어나면 회색으로 바뀌고 꼭짓점에 딱 걸리면 따로 알려 준다. 최댓값과 최솟값을 직접 적어 채점하며(차례로 6·15·4·12 와 0·0·-5·0), 맞히면 각 꼭짓점에 그 값이 적힌다. 일차식마다 최댓값이 나오는 꼭짓점이 (4,2)·(5,0)·(0,4) 로 달라지는 것을 눈으로 확인하게 했다. ③꼭짓점 사냥 — 연립부등식이 만드는 영역을 보여 주고 꼭짓점을 모두 눌러 찾는 놀이 다섯 문제(찾을 꼭짓점 모두 18개). 삼각형·사각형·평행사변형·사다리꼴이 골고루 나오고 꼭짓점은 모두 정수 좌표이며, 어느 문제에도 없어도 되는 군더더기 부등식이 들어 있지 않다. 영역 안이지만 모서리가 아닌 점을 누르면 그 사실을 짚어 주고, 세 번 헤매면 '경계선 두 개가 만나는 자리'라는 힌트를 준다. ④꼭짓점 표로 풀기 — 앞 탭에서 찾은 꼭짓점을 그대로 이어 쓴다. 영역의 꼭짓점에 A·B·C·D 이름이 붙고, 각 꼭짓점의 좌표를 일차식에 대입한 값을 표에 채워 채점한 뒤, 최댓값과 최솟값이 나오는 꼭짓점을 눌러 고른다. 다 맞히면 최댓값 직선(노란 점선)과 최솟값 직선(파란 점선)이 그려져 영역이 두 직선 사이에 쏙 들어가는 모습을 보여 준다. 세 문제는 y ≥ 0, y ≤ x + 4, y ≤ -x + 4 에서 2x + y (최대 8, 최소 -8) / x ≥ -1, y ≥ -1, x + y ≤ 4 에서 3x - y (최대 16, 최소 -8) / x ≥ 0, 1 ≤ y ≤ 4, x + y ≤ 6 에서 x + 2y (최대 10, 최소 2) 이고, 최댓값·최솟값이 나오는 칸이 문제마다 달라지도록 배치했다. 재료가 정해진 실생활 계획 문제는 뒤의 선형계획법 활동에서 다루므로, 이 활동은 영역과 꼭짓점을 다루는 데까지만 담았다.$ov$, now()),
  ($s$economics/mini/linear_programming_lab$s$, $ov$제약 조건 아래에서 이익의 최댓값이나 비용의 최솟값을 찾는 선형계획법을 네 탭으로 연습하는 활동. 앞의 '연립부등식의 영역과 최대·최소' 에서 익힌 꼭짓점 대입법을 실생활 문제에 그대로 쓴다. ①조건을 부등식으로 — 목공방에서 스툴을 x개, 선반을 y개 만든다고 할 때 목재비·도색비 표(스툴 5·2, 선반 3·4, 단위 천원)와 예산(목재비 210천원, 도색비 140천원)을 보고 부등식을 세우는 다섯 단계. 목재비 조건 5x + 3y ≤ 210, 도색비 조건 2x + 4y ≤ 140 을 보기에서 고르고(x와 y의 계수를 바꿔 놓은 미끼와 부등호를 뒤집은 미끼를 넣었다), 빠뜨리기 쉬운 x ≥ 0, y ≥ 0 을 짚은 뒤 두 경계가 만나는 꼭짓점 (30, 20)을 연립해 구한다. 한 단계를 풀 때마다 그 조건이 좌표평면에 더해져 영역이 좁아지고, 다 풀면 꼭짓점 (0,0)·(42,0)·(30,20)·(0,35) 이 표시된다. ②이익을 최대로 — 같은 목공방에서 이익 8x + 12y 를 k 로 놓은 직선을 손잡이로 밀어 본다. 직선이 영역과 만나면 '이만큼은 낼 수 있어요', 벗어나면 '낼 수 없어요' 로 바뀌고 꼭짓점에 딱 걸리면 따로 알려 준다. 최대 이익 480천원을 직접 적어 채점하면 네 꼭짓점의 값(0·336·480·420)을 담은 표가 열린다. 두 물건의 이익 단가를 손잡이로 바꾸면 직선의 기울기가 바뀌어 최선의 계획이 (30,20) → (42,0) → (0,35) 로 옮겨 가고, 63가지 단가 가운데 5가지에서는 두 꼭짓점의 이익이 같아져 그 변 위의 모든 계획이 똑같이 좋다는 것도 보여 준다. ③비용을 최소로 — 반려견 사료 배합 문제로 부등호의 방향이 반대인 경우를 다룬다. A 사료(단백질 20g·칼슘 10g·3천원)와 B 사료(10g·30g·4천원)로 단백질 200g 이상, 칼슘 300g 이상을 채워야 하므로 20x + 10y ≥ 200, 10x + 30y ≥ 300 이 되고 영역이 오른쪽 위로 끝없이 뻗는다. 꼭짓점 (0,20)·(6,8)·(30,0) 에서 비용 3x + 4y 는 80·50·90 이므로 최소는 50천원. '최댓값도 구할 수 있을까?' 라는 물음을 붙여 영역이 열려 있으면 최댓값이 없다는 것을 스스로 확인하게 했다. ④실전 문제 — 표와 예산이 주어진 세 문제를 단계별로 푼다. 베이커리(마들렌·스콘, 3x + 6y ≤ 180, 4x + 2y ≤ 120, 이익 5x + 6y → 최대 220천원 at (20,20)), 텃밭 비료(질소·인, 3x + y ≥ 30, x + 2y ≥ 20, 비용 5x + 4y → 최소 64천원 at (8,6)), 동아리 굿즈(스티커·뱃지, x + 3y ≤ 60, 2x + 3y ≤ 90, 이익 3x + 4y → 최대 135천원 at (45,0)). 특히 세 번째 문제는 두 경계가 만나는 교점 (30,10)의 값 130 보다 가로축 위의 꼭짓점 (45,0)의 값 135 가 더 크도록 꾸며, 교점만 보고 답하면 틀린다는 것을 몸으로 겪게 한다. 모든 문제의 최적값은 격자점 전수 탐색으로 다시 확인했다.$ov$, now()),
  ($s$economics/mini/polygon_region_lab$s$, $ov$지금까지와 방향이 반대인 활동. 부등식 → 영역이 아니라 영역(다각형) → 부등식을 찾는다. 네 탭으로 이루어져 있다. ①도형을 부등식으로 — 노란 점선으로 그려진 다각형을 보고 그 영역을 만드는 부등식 카드를 모두 골라 담는다. 카드를 고를 때마다 고른 부등식들이 겹치는 영역이 보라색으로 칠해져 목표 도형과 곧바로 견줄 수 있다. 삼각형 (1,0)(5,0)(1,4) / 사다리꼴 (0,0)(4,0)(4,2)(0,4) / 오각형 (0,1)(1,0)(4,0)(4,3)(0,3) 세 문제이고, 미끼 카드는 부등호를 뒤집었거나 x와 y의 계수를 바꾼 것이라 하나라도 잘못 담으면 영역이 달라진다. 정답 카드를 하나 빼도 영역이 달라지는지(군더더기가 없는지)까지 확인해 두었다. ②내 도형 만들기 — 제1사분면 격자를 눌러 점을 찍으면 그 점들을 감싸는 볼록 다각형이 만들어지고 각 변이 만드는 부등식이 바로 나온다. 다시 누르면 점이 지워지고 최대 열 개까지 찍을 수 있다. 변 p1 → p2 를 반시계 방향으로 놓았을 때 안쪽 법선이 (-dy, dx) 라는 사실에서 부등식을 뽑고, 계수를 최대공약수로 약분해 x의 계수가 양수가 되도록 정리해 보여 준다. 안쪽에 찍은 점은 회색으로 남아 꼭짓점이 되지 못하는데, 이미 다른 부등식을 모두 만족하니 새 조건이 되지 못한다는 것을 짚어 준다. ③a와 b를 바꾸면 — 오각형 x ≥ 0, y ≥ 0, x ≤ 4, y ≤ 3, x + y ≥ 1 (꼭짓점 A(0,1) B(1,0) C(4,0) D(4,3) E(0,3)) 을 고정해 두고 일차식 ax + by 의 a와 b를 -4에서 4까지 손잡이로 바꾼다. 다섯 꼭짓점의 값이 표로 나오고 최댓값 칸은 노랑, 최솟값 칸은 파랑으로 표시되며 최댓값 직선과 최솟값 직선이 그래프에 함께 그려져 영역이 두 직선 사이에 들어가는 모습을 보여 준다. 81가지 계수 조합에서 최댓값이 나오는 자리가 11가지로 갈리고 그 가운데 21가지에서는 두 꼭짓점이 동시에 최대가 된다. 관찰한 것을 '최댓값과 최솟값은 영역의 꼭짓점에서 나온다', 'a와 b를 바꾸면 직선의 기울기가 바뀌어 답이 나오는 꼭짓점이 옮겨 간다' 두 문장으로 정리하게 한다. ④꼭짓점 미션 — 같은 오각형에서 a와 b를 맞춰 다섯 가지 목표를 이룬다. 최댓값이 D 에서만 나오게 하기(16가지 답), E 에서만 나오게 하기(16가지), 최솟값이 B 에서만 나오게 하기(6가지), 최댓값이 두 꼭짓점에서 함께 나오게 하기(20가지), 다섯 꼭짓점의 값이 모두 같게 하기(a = b = 0 하나뿐)이다. 시작 계수는 어느 미션도 처음부터 풀려 있지 않도록 골랐다.$ov$, now()),
  ($s$economics/mini/matrix_lab$s$, $ov$행렬의 뜻과 네 가지 연산, 그리고 그것을 실제 자료에 쓰는 일까지 다섯 탭으로 다루는 활동. ①행렬 읽기 — 가로줄과 세로줄의 개수를 1에서 4까지 손잡이로 바꾸면 그 꼴의 행렬이 곧바로 그려지고 'm×n 행렬 · 성분 mn개 · n차 정사각행렬인지' 배지가 함께 바뀐다. 성분을 누르면 그 성분이 놓인 행은 파랑, 열은 노랑, 둘이 만나는 자리는 초록으로 밝아져 (i, j) 성분의 뜻을 눈으로 익힌다. 이어지는 '성분 사냥'은 3×4 행렬에서 제1행 제3열처럼 말해 주는 자리를 눌러 맞히는 놀이인데, 열두 성분의 값을 모두 서로 다르게 골라 우연히 맞는 일이 없도록 했다. 마지막은 꼴 읽기·정사각행렬 판별·성분 개수·3차 정사각행렬의 뜻·(2,3) 성분 읽기·같은 꼴 찾기·성분으로 다루는 수까지 일곱 문제의 용어 퀴즈이고, 오답 보기마다 어느 자리를 잘못 보았는지 짚어 준다. ②더하기·빼기·몇 배 — 2×2 와 3×3 을 오가며 A + B, A − B, kA, A + kB 네 연산을 고르고 실수 k 를 -3에서 3까지 움직인다. 결과 행렬의 칸을 누르면 A 와 B 의 같은 자리가 함께 밝아지고 그 칸의 계산식이 나타나, 덧셈·뺄셈·실수배가 모두 '같은 자리끼리' 하는 일임을 보여 준다. 56가지 조합 어디서도 성분이 두 자리를 넘지 않도록 값을 골랐다. 이어 A + B, A − B, 3A − 2B 와 3×3 의 A + B, 2A − B 를 빈칸에 직접 채우는 다섯 문제와, 꼴이 다르면 더할 수 없다는 것, A − B 와 B − A 는 모든 성분의 부호가 반대라는 것을 확인하는 두 문제가 이어진다. ③곱셈의 비밀 — 먼저 2×3·3×2, 3×2·3×2, 2×4·4×1, 1×3·3×3, 3×3·2×3, 4×2·2×5 여섯 쌍으로 '이 순서로 곱할 수 있는가'를 판단하고, 곱할 수 있으면 결과의 꼴까지 고르는 퍼즐을 푼다. 확인을 누르면 가운데 두 수가 초록 또는 빨강으로 물들어 짝이 맞는지 한눈에 보인다. 다음은 A(2×3) = ((2,-1,3),(0,4,-2)) 와 B(3×2) = ((1,5),(-3,2),(4,-1)) 로 AB 의 네 칸을 하나씩 채우는 활동인데, 물음표 칸을 누르면 그 칸을 만드는 A 의 가로줄과 B 의 세로줄이 밝아지고 2·1 + (-1)(-3) + 3·4 같은 곱의 합이 그대로 적힌다. 이어 A = ((1,2),(0,3)), B = ((2,-1),(4,1)) 로 AB = ((10,1),(12,3)) 와 BA = ((2,1),(4,11)) 를 견주어 두 행렬 모두 2차 정사각행렬인데도 순서를 바꾸면 값이 달라지는 것을 확인하고, 2×2·2×2, 2×3·3×2, 1×3·3×1 곱셈 연습 세 문제로 마무리한다. ④스프레드시트 — MMULT 로 행렬의 곱을 구하는 과정을 그대로 흉내 낸 가짜 시트를 준다. 연습 시트에서는 B3:D4 의 2×3 행렬과 F3:G5 의 3×2 행렬을 놓고 ㉠결과의 꼴 고르기 ㉡시트에서 결과가 들어갈 I3:J4 범위를 끌어 잡기 ㉢네 가지 수식 가운데 =MMULT(B3:D4, F3:G5) 고르기 ㉣Ctrl + Shift + Enter 로 확정하기 네 단계를 밟는다. 순서를 뒤집은 수식, SUM, 별표를 쓴 수식이 미끼로 들어 있다. 실습 시트는 편의점 물류창고 세 곳(가람·나루·다솔)의 생수·이온음료·커피 상자 수 ((120,80,60),(90,140,50),(70,60,150)) 와 도매상 세 곳(P·Q·R)의 상자당 값(천원) ((13,12,11),(14,16,15),(23,22,25)) 을 곱해 창고별 총액 ((4060,4040,4020),(4280,4420,4340),(5200,5100,5420)) 을 얻는다. 가람은 P, 나루는 Q, 다솔은 R 로 답이 모두 다르도록 값을 골라, 같은 물건이라도 담긴 비율에 따라 유리한 곳이 달라진다는 것을 보여 준다. ⑤실생활 해결 — 다섯 가지 상황을 골라 가며 푼다. 문구점 두 지점의 3월 초 재고·입고·판매로 말 재고를 구하는 문제(S + I − T), 빵집의 평일 생산량에 주말 1.5배를 더해 한 주 생산량을 5D + 2(1.5D) = 8D 로 정리하는 문제, 세 동아리의 사이즈별 티셔츠 주문량과 세 업체의 사이즈별 단가를 곱해 동아리마다 가장 싼 업체가 나·다·가 로 갈리는 것을 찾는 문제, 카페의 재료 사용량 행렬에 재료 단가 열행렬을 곱해 아메리카노 720원·카페라떼 920원·바닐라라떼 960원의 원가를 구하고 하루 재료비 208,000원까지 계산하는 문제, 축제 부스 이틀 판매량을 더한 뒤 품목 값을 곱해 3반 부스가 452,500원으로 가장 많이 벌었음을 찾는 종합 문제다. 모든 문제는 앞 단계를 맞혀야 다음이 열리며 힌트와 해설을 제공하고, 답은 모두 실제 계산으로 다시 대조했다. 수량과 값은 계산이 깔끔하게 떨어지도록 정한 가상의 값임을 활동 안에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/row_sum_mean_lab$s$, $ov$행렬의 곱으로 각 행의 성분의 합과 평균을 한꺼번에 구하는 방법을 네 탭으로 익히는 활동. ①합 기계·평균 기계 — 세로줄이 각각 3·4·5개인 세 행렬 가운데 하나를 고르고, 오른쪽에 곱할 열행렬의 성분을 1 · 1/2 · 1/3 · 1/4 · 1/5 · 2 여섯 칩에서 골라 끼운다. 끼운 수가 1 이면 '합을 구하는 기계', 그 행렬의 세로줄 개수의 역수이면 '평균을 구하는 기계' 라는 배지가 저절로 붙어, 1/n 의 n 이 가로줄 개수가 아니라 세로줄 개수라는 것을 스스로 발견하게 된다. 행렬을 바꾸면 평균이 되는 칩도 함께 옮겨 간다. 가로줄이나 결과 칸을 누르면 그 줄이 12·1 + 8·1 + 10·1 = 30 처럼 수 하나로 접히는 과정이 그대로 적힌다. 세 행렬은 ((12,8,10),(6,9,21)) · ((8,12,4,16),(20,6,10,8),(14,10,18,6)) · ((10,15,20,5,25),(12,8,16,24,20),(18,22,14,26,10)) 로, 모두 행의 합이 세로줄 개수로 나누어떨어져 평균이 정수가 된다. 이어 곱하는 열행렬의 꼴과 성분을 고르는 문제, 합과 평균을 직접 채우는 문제 등 일곱 단계가 이어진다. ②실생활 해결 — 급식 만족도(3학급×5일, 평균 8·9·7), 밴드부 연습 시간(4명×5일, 합 250·240·300·220 · 하루 평균 50·48·60·44), 학교 매점 네 주 판매(3품목×4주, 합 520·800·400), 학교 텃밭 수확량(3작물×4주, 평균 15·26·11), 게임 대회 결승(4팀×3라운드, 평균 85·91·80·87) 다섯 장면을 고르며 푼다. 표마다 행렬 이름 배지(S·T·P·H·G)를 붙이고 표 아래에 그 표를 옮긴 행렬을 나란히 보여 주며, 가로줄에 수가 몇 개인지에 따라 끼울 수가 1/5·1/4·1/3 로 달라진다는 점을 장면마다 안내한다. 표가 5주로 늘어나면 곱할 성분이 어떻게 바뀌는지 묻는 문제로 일반화까지 짚는다. ③앞뒤로 끼우기 — 세 반이 네 과목을 본 성적표 ((84,90,78,88),(72,69,90,81),(90,84,81,89)) 를 가운데 두고 왼쪽 슬롯(1×3 행행렬)과 오른쪽 슬롯(4×1 열행렬)에 '끼우지 않음 / 모두 1 / 개수의 역수' 를 자유롭게 조합한다. 아홉 가지 조합이 모두 뜻을 가지도록 값을 골랐다 — 반별 총점 340·312·344, 반별 평균 85·78·86, 과목별 총점 246·243·249·258, 과목별 평균 82·81·83·86, 전체 합 996, 전체 평균 83 이 모두 정수로 떨어진다. 오른쪽에 끼우면 가로줄이, 왼쪽에 끼우면 세로줄이, 양쪽에 끼우면 1×1 수 하나가 남는 것을 눈으로 확인하고, 여섯 가지 목표(반별 총점·반별 평균·과목별 총점·과목별 평균·모든 점수의 합·전체 평균)를 슬롯 조합으로 맞추는 미션을 푼다. 여섯 미션은 서로 다른 조합이고 처음 상태로 이미 풀려 있는 것은 없다. 마지막에는 반 평균의 합(996÷4 = 249)과 과목 평균의 합(996÷3 = 332)이 왜 다른지까지 따져 본다. ④빈칸 탐정 — 거꾸로 지워진 칸을 가로 합과 세로 합으로 되살리는 퍼즐 다섯. 물에 젖은 재고표(2×3, 두 칸), 가로·세로 합이 모두 남은 장부(3×3, 세 칸), 합계 없이 평균만 남은 성적표(3×3, 평균에 세로줄 개수를 곱해야 한다), 번진 네 주 기록(3×4), 그리고 첫 줄의 가로 합마저 지워져 세로 합부터 써야 하는 표(3×3)로 난이도가 올라간다. 다섯 문제 모두 0 이상 40 이하의 정수 범위를 완전탐색해 답이 하나뿐임을 확인했다. 점수·시간·수량은 모두 계산이 깔끔하게 떨어지도록 이 활동을 위해 정한 가상의 값임을 활동 안에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/inverse_matrix_lab$s$, $ov$역행렬이 있을 조건과 구하는 방법, 그리고 그 쓰임을 네 탭으로 다루는 활동. ①역행렬 실험실 — a, b, c, d 네 손잡이를 -5에서 5까지 움직이면 행렬 A 와 함께 대각선을 바꾸고 나머지 부호를 바꾼 짝 행렬이 나란히 그려지고(대각선은 초록, 나머지는 자홍으로 물들여 무엇을 어떻게 바꾸는지 보이게 했다), 행렬식 ad − bc 가 실제 수로 적히며 '역행렬이 있어요 / 없어요' 가 곧바로 바뀐다. 역행렬은 행렬식이 1 이나 -1 이면 정수 행렬로, 그 밖에는 분수를 앞에 뺀 꼴로 보여 주고, '정말 단위행렬이 될까' 버튼을 누르면 A 와 역행렬을 곱한 결과가 실제로 단위행렬이 되는 것을 확인할 수 있다. 행렬식이 0 이면 역수를 만들 수 없다는 안내와 함께 두 줄이 같은 방향인지 살펴보게 한다. 미션 네 개는 역행렬이 없는 행렬 만들기(14641가지 가운데 833가지가 답), 행렬식이 1인 행렬 만들기(308가지), 행렬식이 -4인 행렬 만들기(492가지), 자기 자신이 역행렬인 행렬 만들기(70가지)이고, 시작 행렬 ((2,3),(1,4)) 은 어느 미션도 처음부터 풀려 있지 않도록 골랐다. 이어 행렬식 구하기, 역행렬 채우기, 네 행렬 가운데 역행렬이 없는 것 고르기, 행렬식이 1이 아닐 때 분수 뒤에 곱할 짝 행렬 채우기 등 일곱 단계를 푼다. ②값 알아내기 — AX = B 를 X = A⁻¹B 로 푸는 실생활 문제 다섯. 가격표가 지워진 분식집(떡볶이 4천원·순대 3천원, 행렬식 1), 어른과 청소년 표값을 구하는 영화관(1만원·8천원, 행렬식 5), 품목별 값이 안 찍힌 문구점 영수증(공책 2천원·볼펜 1천원, 행렬식 -1), 두 학기 주문 기록만 남은 동아리 단체복(티셔츠 1만3천원·모자 1만원, 행렬식 -2), 질소와 인을 맞추는 텃밭 비료 배합(A 10kg·B 30kg, 행렬식 10). 행렬식을 1 · 5 · -1 · -2 · 10 으로 골고루 두어 역행렬이 정수로 떨어지는 경우와 1/det 를 앞에 빼야 하는 경우를 함께 겪게 했고, 다섯 문제 모두 해가 양의 정수다. 영화관 문제에는 '행렬식이 5인데도 왜 답이 정수로 나왔을까' 를 묻는 문항을 붙여 짝 행렬을 곱한 값이 5의 배수였기 때문임을 짚는다. ③행렬 암호 — 역행렬의 가장 멋진 쓰임. 한글 마흔 자에 번호를 매긴 글자표를 주고, 두 글자의 번호를 열행렬로 묶어 열쇠 행렬을 곱하면 암호 두 수가 된다. 글자표에서 두 글자를 눌러 자기 암호를 직접 만들어 보고, 이어 받은 암호에 열쇠의 역행렬을 곱해 원래 글자 번호를 되찾는 미션 네 개를 푼다(두 글자 둘, 네 글자 둘, 도중에 열쇠가 바뀐다). 답을 맞히면 숨어 있던 말이 글자로 나타난다. 두 열쇠 ((2,1),(3,2)) 와 ((3,2),(4,3)) 은 모두 행렬식이 1 이라 역행렬이 정수 행렬이고, 1600가지 글자쌍이 서로 다른 암호로 옮겨져 되돌릴 때 헷갈리지 않는다. 왜 하필 행렬식이 1인 열쇠를 골랐는지(정수라야 글자 번호가 된다), 곱해서 만든 것을 무엇으로 되돌리는지를 묻는 문항으로 마무리한다. ④행렬식 사냥 — 카드 열두 장 가운데 역행렬이 있는 것만 골라 담는 놀이. 확인을 누르면 카드마다 행렬식이 드러나고 초록·빨강 테두리로 맞고 틀림을 알려 주며, 행렬식이 0 인 카드에는 '아래 줄이 위 줄의 2배', '왼쪽 세로줄이 모두 0' 처럼 그 까닭이 함께 뜬다. 역행렬이 있는 카드와 없는 카드를 여섯 장씩 반반으로 두었고, 없는 여섯 장은 모두 한 줄이 다른 줄의 실수배이거나 한 줄이 통째로 0 인 것들이다. 마지막에는 그 공통점을 스스로 정리하고, AB = E 이면 BA 도 E 가 된다는 역행렬의 교환법칙까지 확인한다. 값과 함량은 모두 계산이 깔끔하게 떨어지도록 이 활동을 위해 정한 가상의 값임을 활동 안에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/linear_system_lab$s$, $ov$연립일차방정식 하나를 식 · 행렬 · 두 직선 세 가지 표현으로 함께 보며 역행렬로 해를 구하는 네 탭 활동. ①두 직선 실험실 — a, b, m, c, d, n 여섯 손잡이(계수는 -5~5, 상수항은 -8~8)를 움직이면 연립방정식과 행렬 방정식 AX = B 와 좌표평면의 두 직선이 동시에 바뀐다. 화면이 -10~10 이라 원점에서 직선까지의 거리가 8 을 넘지 않아 어느 자리에서도 두 직선이 늘 보이고, 손잡이로 만들 수 있는 직선 2040가지가 모두 화면 안에 그려지는 것을 전수로 확인했다. 행렬식 ad - bc 가 실제 수로 적히고 '한 점에서 만나요 / 두 직선이 겹쳐요 / 두 직선이 나란해요' 배지와 '해가 하나 / 무수히 많아요(부정) / 없어요(불능)' 가 함께 바뀌며, 겹친 경우에는 아래 직선을 굵게 깔아 두 직선이 포개진 것이 눈에 보이게 했다. 행렬식이 0 이 아니면 X = A⁻¹B 를 분수까지 조판해 보여 주고 교점에 좌표를 붙인다. x와 y의 계수가 모두 0 이라 직선이 되지 못하는 자리도 따로 안내한다. 미션은 두 직선을 나란하게 만들기, 완전히 겹치게 만들기, 교점을 (2, -1) 로 만들기, 두 직선을 서로 수직으로 만들기(법선끼리 수직이므로 ac + bd = 0) 네 가지이고, 시작 상태 2x + y = 4, x + 3y = 7 (행렬식 5, 교점 (1,2)) 은 어느 미션도 처음부터 풀려 있지 않다. ②역행렬로 풀기 — 다섯 문제를 그래프와 나란히 두고 단계별로 푼다. x + 2y = 7, 3x - y = 7 (행렬식 -7, 해 (3,2)) / 3x + 4y = 10, x + y = 3 (행렬식 -1, 해 (2,1)) / 5x - 2y = 22, 3x + y = 11 (행렬식 11, 해 (4,-1)) / 2x + 5y = 1, x + 3y = 1 (행렬식 1, 해 (-2,1)) / 2x + 3y = 5, 4x + 6y = 7 (행렬식 0). 첫 문제에서는 연립방정식을 AX = B 로 옮길 때 A 가 무엇인지부터 고르게 하고(전치한 것, 상수항, 부호를 놓친 것이 미끼다), 행렬식이 ±1 일 때만 역행렬을 직접 채우게 하며 그 밖에는 짝 행렬을 채운 뒤 마지막에 나누도록 해서 분수를 입력할 일이 없다. 마지막 문제는 행렬식이 0 이라 역행렬이 없어 이 방법으로 풀 수 없고, 아래 식이 위 식의 두 배인데 상수항만 어긋난다는 것을 짚은 뒤 '만약 4x + 6y = 10 이었다면' 을 물어 부정과 불능의 갈림을 확인한다. ③세 갈래 판정 — 카드 열두 장을 '해가 하나 / 무수히 많다 / 없다' 로 가른다. 답을 고르고 확인을 눌러야 두 직선이 나타나므로 먼저 행렬식으로 판단한 뒤 그래프로 검산하는 흐름이 된다. 세 갈래가 넷씩 고르게 들어 있고, 해가 하나인 네 장은 교점이 모두 정수이며 화면 안에 들어온다. 카드마다 '아래 식이 위 식의 꼭 2배라 같은 직선', '계수는 2배인데 상수항은 4가 아니라 7 이라 나란해요', '좌변이 똑같은데 우변만 달라 함께 참이 될 수 없어요' 처럼 까닭이 붙는다. 마지막에는 부정과 불능을 가르는 것이 'x와 y의 계수가 비례하는지' 가 아니라 '상수항까지 같은 비로 비례하는지' 임을 정리한다. ④실생활 해결 — 여섯 장면. 성공한 슛 12개와 얻은 점수 29점으로 2점슛 7개와 3점슛 5개를 찾는 농구 기록, 동전 30개와 9,400원으로 500원짜리 16개와 100원짜리 14개를 찾는 저금통, 차량 25대와 바퀴 80개로 승용차 15대와 오토바이 10대를 찾는 주차장, 버스 8대와 정원 280명으로 45인승과 25인승 4대씩을 찾는 체험학습 배정. 500x + 100y = 9400 을 5x + y = 94 로, 4x + 2y = 80 을 2x + y = 40 으로, 45x + 25y = 280 을 9x + 5y = 56 으로 줄이는 단계를 따로 두어 계수를 간단히 하면 행렬식도 다루기 쉬워진다는 것을 겪게 한다. 나머지 두 장면은 일부러 풀 수 없게 만들었다. 간식 세트는 B 가 A 의 꼭 두 배인데 값이 16,000원이 아니라 15,000원이라 두 조건이 서로 어긋나 해가 없고(불능), 문구 세트는 개수도 값도 정확히 두 배라 B 가 새로 알려 주는 것이 없어 해가 무수히 많다(부정). 마지막에는 값을 정하려면 비율이 다른 새 묶음의 값이 하나 더 있어야 한다는 것까지 묻는다. 금액과 개수는 모두 계산이 깔끔하게 떨어지도록 이 활동을 위해 정한 가상의 값임을 활동 안에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/matrix_use_lab$s$, $ov$행렬이 실제로 쓰이는 네 가지 자리를 모두 조작해 보는 활동. 앞의 둘은 역행렬이, 뒤의 둘은 행렬의 곱이 주인공이다. ①균형가격 찾기 — 수요가 값에 민감한 정도와 값이 0 일 때 사려는 양, 공급 쪽의 같은 두 값까지 네 손잡이를 움직이면 수요함수와 공급함수, 두 곡선의 그래프, 행렬 방정식이 동시에 바뀌고 균형점에 점선이 내려와 좌표가 붙는다. 손잡이가 멈추는 20,736 가지 자리를 전수로 훑어 균형점이 언제나 화면 안에 들어오는 것을 확인했다. 수요 y = -d·x + q 와 공급 y = s·x + p 를 옮기면 A = ((d, 1), (-s, 1)) 이 되어 행렬식이 d + s 로 늘 양수이고, 그래서 균형점이 언제나 딱 하나 있다는 것을 배지로 짚어 준다. 이어 과일주스(행렬식 50, 균형 (4, 220)), 수면양말(40, (8, 280)), 무선 이어폰(60, (10, 360)), 화분 세트(30, (11, 378)) 네 시장을 단계별로 푼다. 이어폰 문제에는 균형보다 비싼 12천원에서 수요 290개와 공급 410개로 물건이 남아 값이 내려간다는 것을 묻는 문항을, 화분 문제에는 인기가 올라 상수항만 510에서 600으로 바뀌면 균형가격이 11에서 14로 오른다는 것을 묻는 문항을 붙였다. ②생산량 되짚기 — 제품 1개에 드는 자원 표와 실제로 쓴 자원 총량만 주고 만든 개수를 역행렬로 거꾸로 알아낸다. 빵집(밀가루·버터 → 식빵 12개, 케이크 5개, 행렬식 10), 가구 공방(목재·나사 → 의자 3개, 책상 8개, -6), 음료 공장(과즙·설탕 → 주스 25병, 에이드 15병, 5), 도자기 공방(흙·유약 → 컵 12개, 접시 8개, 1) 네 곳이다. 계수가 300, 4600 처럼 크므로 가로줄마다 알맞은 수로 나누어 간단히 하는 단계를 따로 두었고, 어느 수로 나눌지 고르게 하는 문항도 넣었다. 행렬식이 1 인 도자기에서는 나누는 단계가 사라져 계산이 가장 편하다는 것을 겪게 한다. ③사용자 수 예측 — 두 앱을 계속 쓸 확률과 처음 사용자 수를 손잡이로 정하면 전이행렬이 만들어지고, '한 해 보내기' 와 '10년 건너뛰기' 단추로 사용자 수가 막대로 움직인다. 전체 인원은 그대로인 채 두 앱 사이에서만 옮겨 다니는 것, 오래 지나면 갈아타는 비율의 반대 비로 굳는 것을 눈으로 보게 했다. 손잡이가 멈추는 자리를 전수로 훑어 가로줄의 합이 늘 1 이고 굳는 값이 300년 뒤 값과 일치함을 확인했다. 문제는 배달앱 두 곳(전이행렬 ((0.8,0.2),(0.3,0.7)), 처음 500명과 300명 → 1년 뒤 490·310, 2년 뒤 485·315, 굳는 값 480·320)과 음원앱 두 곳(((0.9,0.1),(0.4,0.6)), 600명과 400명 → 1년 뒤 700·300, 3년 뒤 775·225, 굳는 값 800·200)이고, 전이행렬의 (1,2) 성분이 무슨 뜻인지, 굳는 값이 처음 사용자 수에 따라 달라지는지까지 묻는다. ④사회 연결망 — 다섯 사람을 원 위에 놓고 선을 눌러 이었다 끊었다 하면 인접행렬이 곧바로 바뀌고, 성분이 모두 1 인 열행렬을 곱한 친구 수와 영향력 1등이 함께 갱신된다. 'A² 보기' 를 켜면 두 다리로 가는 길의 수가 나타나고 대각선이 그 사람의 친구 수와 같다는 것도 확인할 수 있다. 미션은 혼자인 사람 없애기(1024가지 가운데 768), 선을 딱 4개만 써서 다섯 명 모두 잇기(125), 누구든 두 다리 안에 닿게 하기(368), 영향력 1등을 한 명으로 만들기(525)이고, 시작 상태는 넷이 한 줄로 이어지고 한 명은 혼자라 어느 미션도 처음부터 풀려 있지 않다. 문제용 연결망은 친구 수가 1·4·3·3·3 이라 1등이 한 명뿐이고, 친구 수를 구하는 방법과 소식을 퍼뜨리기 좋은 사람, 두 다리로 가는 길의 수, A² 의 대각선이 뜻하는 것까지 다섯 단계로 묻는다. 값·인원·사용량은 모두 계산이 깔끔하게 떨어지도록 이 활동을 위해 정한 가상의 값임을 활동 안에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/limit_lab$s$, $ov$함수의 극한을 계산이 아니라 눈으로 익히는 네 탭 활동. ①한없이 가까이 — 여섯 함수(3x - 4, x² - 2x, (x² - 5x + 6)/(x - 2), (2x² - 2)/(x - 1), 1/x, 상수함수 4) 가운데 하나를 고르고 '한 걸음 더 가까이' 단추를 누를 때마다 x 가 a 에 10배씩 가까워진다. 왼쪽에서 다가가는 값과 오른쪽에서 다가가는 값이 표에 한 줄씩 쌓이고, f(x) 가 극한값과 앞에서부터 몇 자리나 같아졌는지가 초록으로 물들어 수렴이 눈에 보인다. 그래프도 같은 폭으로 확대되어 분홍 점 둘이 양쪽에서 초록 점으로 모여 가는데, 여섯 함수 × 여섯 단계 모든 자리에서 극한값이 화면 안에 들어오도록 확대 상자를 계산한다. 구멍이 있는 두 함수는 x = a 에서 속이 빈 동그라미로 그려지고 '함숫값은 없지만 극한은 있다' 는 안내가 붙는다. 아무리 좁혀도 x 가 a 와 같아지지 않는다는 것, 그래서 x = a 의 값이 극한과 상관없다는 것을 세 문항으로 정리한다. ②구멍이 있어도 — 극한값이 같은 세 함수를 나란히 놓고 x = a 자리만 다르다는 것을 본다. 세트 1 은 x 가 2 에 가까워질 때로 이어짐 x + 1, 뚫림 (x² - x - 2)/(x - 2), 어긋남 x + 1 (x ≠ 2)에 h(2) = 1 이고 셋 다 극한값이 3 이다. 세트 2 는 x 가 -1 에 가까워질 때로 x - 1, (x² - 1)/(x + 1), 그리고 h(-1) = 1 인 어긋난 함수이며 극한값은 모두 -2 다. 세 그래프를 먼저 눈으로 견준 뒤 단추를 눌러 극한값과 함숫값을 함께 드러내게 했다. 극한값은 함숫값과 같을 수도, 다를 수도, 함숫값이 아예 없을 수도 있다는 것이 이 탭의 결론이다. ③극한의 성질 — x → 2 에서 극한을 가지는 다섯 함수(x + 1, x², 5, (x² - x - 2)/(x - 2), x - 2)를 f 와 g 로 골라 f + g, f - g, cf, fg, f/g 로 조합한다. 성질로 예측한 값과 x 에 2 바로 옆 값을 넣어 얻은 실제 값이 함께 뜨고 조합한 함수의 그래프도 그려진다. 다섯 함수 × 다섯 함수 × 다섯 연산 × 상수 일곱 가지, 모두 840가지 조합에서 예측값과 실제 값이 일치함을 확인해 두었다. g 로 극한값이 0 인 x - 2 를 골라 나눗셈을 누르면 '성질 (4)에는 M ≠ 0 이라는 단서가 붙어 있다' 는 안내가 뜬다. 구멍이 있는 함수를 골라도 예측이 그대로 맞는 것을 보여 주어, 성질의 조건이 '함숫값이 있을 것' 이 아니라 '극한값이 있을 것' 임을 짚는다. 문항은 lim f = 3, lim g = -2 로 두고 합 1, 2f - 3g 의 12, fg 의 -6 을 구한 뒤 분모의 극한이 0 인 경우를 따지고, 마지막에 (2x² + 3)(x - 4) 의 x → 1 극한 -15 를 덩어리로 나눠 구한다. ④그래프 탐정 — 그래프 여덟 장을 보고 극한값과 함숫값을 따로 답한다. 숫자를 적거나 '극한이 없어요' · '값이 없어요' 단추를 누르는 방식이라 두 물음이 다르다는 것이 손에 남는다. 이어진 직선과 포물선, 한 점이 뚫린 직선과 포물선, 한 점만 딴 자리에 찍힌 그래프, 그리고 왼쪽과 오른쪽이 다른 높이로 가는 끊긴 그래프까지 네 유형을 고르게 섞었다. 끊긴 유형 하나는 2kg 을 경계로 3,000원에서 4,000원으로 뛰는 택배 요금이고, 뚫린 유형 하나는 거리가 s(t) = t² + t 일 때 2초부터의 평균 속도 (s(t) - s(2))/(t - 2) = t + 3 이다. t = 2 에서는 0 으로 나누게 되어 값이 없지만 극한은 5 이고, 그것이 바로 2초 순간의 속도라는 것을 마지막 문항에서 짚어 다음 단원의 미분과 이어 준다. 택배 요금과 거리의 수치는 개념을 보여 주기 위해 이 활동에서 정한 가상의 값임을 활동 안에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/derivative_lab$s$, $ov$평균변화율에서 출발해 미분계수와 도함수가 어떻게 생겨나는지를 다섯 탭으로 따라가는 활동. ①증분과 평균변화율 — 일차함수 2x - 1, 이차함수 -x² + 2x + 3, 삼차함수 x³ - 3x, 상수함수 3 가운데 하나를 고르고 시작 자리 a 와 끝 자리 b 를 손잡이로 움직이면 그래프 위에 Δx 와 Δy 가 청록·보라 직각삼각형으로 그려지고 두 점을 잇는 할선이 함께 돌아간다. Δx = b - a, Δy = f(b) - f(a), 그리고 Δy/Δx 가 분수 꼴 그대로 조판되어 평균변화율이 곧 직선 AB 의 기울기임을 눈으로 잇는다. 일차함수에서는 a 와 b 를 어떻게 바꾸어도 2 가 나오고, 상수함수에서는 Δy 가 늘 0 이며, 이차함수는 -(a + b) + 2, 삼차함수는 a² + ab + b² - 3 으로 구간에 따라 값이 달라진다. a 와 b 를 같게 두면 Δx = 0 이 되어 분모가 0 이라는 경고가 뜨는데, 이것이 다음 탭의 출발점이 된다. 문항은 직선의 평균변화율이 일정한 까닭, -x² + 2x + 3 에서 0 → 2 의 평균변화율이 0 인 것(f(0) = f(2) = 3), x³ - 3x 에서 -1 → 1 의 평균변화율 -2, 그리고 평균변화율이 할선의 기울기인 까닭 네 가지다. ②할선에서 접선으로 — 접점 a 를 정하고 Δx 를 1 · 0.5 · 0.2 · 0.1 · 0.05 · 0.02 · 0.01 · 0.001 로 여덟 단계 좁혀 간다. 지나온 할선이 흐린 분홍으로 잔상처럼 남아 할선이 초록 접선 쪽으로 눕는 모습이 그대로 쌓이고, 오른쪽(+Δx)과 왼쪽(-Δx)의 할선 기울기가 표에 한 줄씩 쌓이며 같은 값으로 모인다. 네 함수는 x² - 4x + 5 (f' = 2a - 4), x³ - 3x (3a² - 3), -½x² + 3x (-a + 3), 2x + 1 (늘 2) 이고, 일차함수에서는 할선이 처음부터 접선과 겹쳐 좁힐 것이 없다는 것을 겪는다. Δx 를 아예 0 으로 둘 수 없는 까닭, f'(3) = 2, 접선이 수평이 되는 x = 2, 일차함수의 f'(-1) = 2, 미분계수가 접선의 기울기라는 것까지 다섯 문항을 푼다. ③미분계수 모으기 — 이 활동의 핵심 탭. 위에는 원래 함수와 움직이는 접선, 아래에는 빈 좌표평면을 두고 '여기 찍기' 로 (a, f'(a)) 를 하나씩 찍거나 '자동으로 쭉 찍기' 로 왼쪽 끝부터 오른쪽 끝까지 훑어 점을 깔 수 있다. 점이 여덟 개를 넘으면 '점을 이어 보기' 가 열려 도함수의 그래프가 나타난다. 네 함수를 x³ - 3x → 3x² - 3, x² - 4x + 5 → 2x - 4, 2x - 1 → 2, 3 → 0 순서로 두어 삼차 → 이차 → 일차 → 상수로 차수가 하나씩 내려가는 것이 보이게 했다. 삼차함수에서는 봉우리(-1)와 골짜기(1) 자리에서 점이 x 축에 닿고, 일차함수에서는 점들이 가로선 하나에 모두 올라앉는다. 점들이 만든 모양이 이차함수라는 것, 일차함수의 도함수가 상수함수인 까닭, 도함수에 x = a 를 넣은 것이 미분계수라는 것, f'(2) = 9, 접선이 수평인 자리가 두 군데라는 것까지 다섯 문항으로 정리한다. ④미분 공식 — 지수 n 을 1 에서 5 까지 손잡이로 올리면 xⁿ 과 그 도함수가 큰 글씨로 바뀌고 '지수 n 이 앞으로', '지수는 n-1 로' 두 배지가 과정을 짚어 주며, n 까지의 결과가 표에 쌓인다. 상수 c 를 -3 · 0 · 2 · 7 로 바꾸어도 도함수가 늘 0 인 것을 따로 확인한다. 이어 p x³ + q x² + r x + s 의 네 계수를 손잡이로 잡으면 식과 도함수의 식, 그리고 두 그래프가 동시에 바뀌고, 네 항 카드가 색으로 짝지어져 각 항이 무엇으로 바뀌는지 보인다. 카드를 누르면 지수가 내려오는 까닭과 상수항이 사라지는 까닭이 나오고, 계수가 0 인 항은 흐려진다. (x⁵)' = 5x⁴, 4x³ - 2x² + 7 의 도함수 12x² - 4x 와 f'(1) = 8, 상수함수 -5 의 도함수 0, x⁴ - 2x³ + 5x 에서 f'(1) = 3, 3x² - 12x + 7 에서 f'(x) = 0 이 되는 x = 2 까지 여섯 문항을 푼다. ⑤경제 속 순간변화율 — 네 장면에서 도함수를 읽는다. 쿠키 공방의 비용 C(x) = x² + 20x + 300 (천원)과 한계비용 C'(x) = 2x + 20 (C'(10) = 40 이고 실제 C(11) - C(10) = 41 이라 거의 같다), 광고비와 매출 R(x) = -2x² + 120x 와 R'(x) = -4x + 120 (30 만원에서 R' 이 0 이 되며 매출이 1,800 만원으로 가장 크고 그 뒤로는 음수), 앱 구독자 N(t) = t³ - 12t² + 60t 와 N'(t) = 3t² - 24t + 60 (최솟값이 t = 4 에서 12 라 늘 양수 — 계속 늘지만 속도가 느려졌다 다시 빨라진다), 중고차 값 V(t) = 10t² - 300t + 2000 과 V'(t) = 20t - 300 (줄곧 음수이되 0 에 가까워져 떨어지는 속도가 느려진다). 손잡이로 자리를 옮기면 위 그래프에 접선이 따라붙고 아래 도함수 그래프에 지금 자리가 주황 점으로 표시되며, 순간변화율과 '실제로 1 만큼 갔을 때의 변화' 를 나란히 놓아 둘이 가깝지만 같지는 않다는 것까지 보여 준다. 한계비용의 뜻, R'(x) = 0 이 되는 광고비 30 만원, R'(40) = -40 의 뜻, V'(5) = -200 을 묻는 다섯 문항으로 마무리한다. 금액과 인원은 모두 계산이 깔끔하게 떨어지도록 이 활동을 위해 정한 가상의 값임을 활동 안에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/marginal_lab$s$, $ov$경제학에서 쓰는 네 가지 '한계' 개념이 모두 같은 도함수라는 것을 네 탭으로 겪게 하는 활동. ①한계효용 — 아이스 레모네이드 U(x) = -x² + 13x, 노래방 한 곡 U(x) = -x² + 16x, 피자 한 조각 U(x) = -2x² + 22x 가운데 하나를 고르고 '한 잔 더' 단추를 누를 때마다 총효용 막대가 하나씩 쌓이며 방금 늘어난 몫이 노란 화살표로 표시된다. 오른쪽 평면에는 그 몫이 한 칸짜리 보라 막대로 계단처럼 쌓이고 한계효용함수의 직선이 겹쳐 그려지는데, 이차함수에서는 [k, k+1] 의 평균변화율이 한가운데 k + 0.5 에서의 미분계수와 정확히 같으므로 막대 꼭대기의 한가운데(노란 점)가 직선 위에 정확히 올라앉는다. 레모네이드는 한계효용이 12 10 8 6 4 2 0 -2 로 2 씩 줄어 7잔째에 0 이 되고 8잔째에는 음수가 되며, 피자는 4 씩 줄어 6조각째에 0 이 된다. 이어 기준 소비량을 정하고 Δx 를 1 → 1/2 → 1/4 → 1/8 → 1/16 로 반씩 줄이면 평균변화율이 표에 쌓이며 U'(x) 로 다가가는 것을 확인한다 (x = 3 에서 6, 6.5, 6.75, 6.875, 6.9375 → 7). 한계효용 8 구하기, 체감하는 까닭, U'(5) = 3, 한계효용함수가 곧 도함수라는 것 네 문항을 푼다. ②한계비용 — 수제 비누 C(x) = x³ - 12x² + 60x + 100 (한계비용 3x² - 24x + 60, 최소 12 at 4), 원두 로스터리 C(x) = 2x² + 24x + 180 (4x + 24, 줄곧 증가), 3D 프린터 키링 C(x) = x³ - 6x² + 20x + 60 (3x² - 12x + 20, 최소 8 at 2) 세 장면을 손잡이로 움직인다. 비용 곡선에 접선이 따라붙고 아래 한계비용 곡선에 지금 자리가 주황 점으로 뜨며, 접선의 기울기와 '실제로 한 개 더 만든 비용' 을 나란히 놓아 둘이 가깝지만 같지는 않다는 것을 보여 준다. 한계비용이 가장 작아지는 자리를 손잡이로 찾는 미션이 있고, 줄곧 늘기만 하는 로스터리에는 그런 자리가 없다는 것까지 알려 준다. C'(2) = 24, 가장 싼 생산량 4개, 한계비용의 뜻, C'(10) = 64, 그리고 고정비가 180 에서 280 으로 바뀌어도 상수항은 미분하면 0 이라 한계비용이 그대로라는 것 다섯 문항을 푼다. ③한계생산량 — 빵집 주방 P(x) = -x³ + 15x² + 72x (한계생산량 -3x² + 30x + 72 = -3(x - 12)(x + 2), 최대 147 at 5, 0 at 12), 배추밭 P(x) = -x² + 20x (-2x + 20, 0 at 10), 자동 조립 라인 P(x) = 25x (늘 25) 세 장면이다. '한 명 더 뽑기' 단추를 누르면 일손 이모지가 한 명씩 늘고 생산량과 한계생산량이 함께 바뀌며, 한계생산량이 음수가 되면 배지가 붉게 바뀌어 사람을 더 뽑는 것이 손해임을 알린다. 한계생산량이 0 이 되는 자리를 찾는 미션에서 빵집은 12명(생산량 1,296개로 최대), 배추밭은 10명이고 조립 라인에는 그런 자리가 없다. P'(2) = 120, 0 이 되는 12명, P'(13) = -45 의 뜻, 조립 라인의 한계생산량 25, 그리고 함께 쓰는 주방과 밭이 정해져 있어 생기는 수확체감까지 다섯 문항을 푼다. ④한계수입 — 가격 x 에 대한 판매량 f(x) 가 주어지고 수입은 g(x) = x·f(x) 라는 것에서 출발한다. 버블티 f(x) = -30x + 240 → g(x) = -30x² + 240x (g' = -60x + 240, 4천원에서 120잔 480천원 최대), 공연 티켓 f(x) = -25x + 400 → g(x) = -25x² + 400x (8만원에서 200장 1,600만원), 전자책 f(x) = -50x + 600 → g(x) = -50x² + 600x (6천원에서 300권 1,800천원) 세 장면이다. 가로가 판매량, 세로가 가격인 직사각형을 그려 그 넓이가 곧 수입임을 보이고, 값을 올리면 세로는 길어지고 가로는 짧아지는 모습과 가장 넓은 모양(노란 점선)을 함께 보여 준다. 한계수입이 양수면 '아직 올릴 여지가 있다', 음수면 '너무 비싸게 매겼다', 0 이면 '바로 여기' 라는 안내가 부호에 따라 바뀌고, 수입이 가장 커지는 값을 찾는 미션이 붙는다. f(2) = 180잔, g(x) = x(-30x + 240) 의 전개, g'(x) = 0 인 가격 4천원, 그때의 수입 480천원, g'(6) = -120 일 때 값을 내려야 한다는 판단까지 다섯 문항을 푼다. 네 탭 모두 'Δy/Δx 를 구한 뒤 Δx 를 0 으로 보낸다' 는 같은 틀이고, 그래서 한계○○함수는 도함수, x = a 에서의 한계○○는 미분계수라는 것이 활동 전체의 결론이다. 효용·비용·생산량·판매량의 수치는 모두 계산이 깔끔하게 떨어지도록 이 활동을 위해 정한 가상의 값임을 활동 안에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/dilemma_lab$s$, $ov$죄수의 딜레마를 네 탭으로 다루는 활동. 수업 자료의 죄수 이야기 대신 같은 구조의 새 상황 다섯을 쓰고, 숫자는 모두 클수록 좋은 점수로 통일했다(형량처럼 작을수록 좋은 수로 두면 부등호가 뒤집혀 헷갈리기 때문). 다섯 상황은 축제 솜사탕 부스(값 지키기·값 깎기, R40 T60 P25 S10 만원), 라면 광고 경쟁(R50 T70 P35 S20 억원), 마을 앞바다 고기잡이(적당히·싹쓸이, R30 T45 P12 S5 상자), 둘이 하는 조별 과제(열심히·묻어가기, R90 T95 P70 S60 점), 두 나라의 탄소 줄이기(R60 T80 P30 S20 점)이고 모두 T > R > P > S 와 2R > T + S 를 지킨다. ①딜레마 실험실 — 수업 자료처럼 칸을 대각선으로 갈라 위쪽 노랑은 나, 아래쪽 파랑은 상대의 보수를 적은 보수표를 띄우고 「상대가 값을 지킨다면」 「상대가 값을 깎는다면」 단추를 누르면 그 줄만 밝아지고 내게 더 좋은 칸에 초록 체크가 붙는다. 두 경우를 모두 눌러 보면 상대가 무엇을 하든 배신이 낫다는 것이 드러나며 지배전략 안내가 뜨고, 둘 다 배신한 칸이 분홍으로 반짝인다. 축제 부스에서는 둘 다 깎아 25만원씩인데 둘 다 지켰다면 40만원씩이었다는 것을 15만원 손해로 짚어 준다. 문항 넷: 상대가 지킬 때 깎으면 60만원 / 상대가 깎을 때도 깎는 쪽이 유리 / 둘 다 깎으면 25만원 / 각자의 똑똑한 선택이 모여 둘 다 손해가 되는 까닭. ②한 판 승부 — 네 상대와 직접 겨룬다. 믿음이(열 판에 여덟 판쯤 협력), 여우(여덟 판쯤 배신), 동전이(반반), 거울이(내 직전 선택을 그대로 따라 함)이고, 내 선택을 누르면 상대가 「고민 중」 하고 깜빡인 뒤 두 선택이 함께 공개되며 이번 판 점수와 누적 점수가 갱신되고 보수표의 해당 칸이 반짝인다. 상대의 선택은 반드시 내가 고른 뒤에 정해져 미리 알 수 없고, 거울이와 겨룰 때만 내 선택이 다음 판에 돌아와 반복 게임을 맛보게 한다. 문항 셋: 한 판뿐이면 배신이 유리한 까닭 / 거울이와 계속 협력하면 매 판 40만원 / 한 판 깎으면 다음 판에 25만원으로 떨어진다는 것. ③전략 리그 — 여섯 전략(늘 협력, 늘 배신, 맞대응, 앙갚음, 너그러운 맞대응, 엇갈이) 가운데 둘을 골라 10판을 붙인다. 「한 판씩」과 「자동으로 쭉」으로 라운드가 하나씩 열리며 두 사람의 선택이 카드로 쌓이고 누적 점수 막대가 자란다. 「리그 열기」를 누르면 여섯 전략이 자기 자신을 포함해 모두 서로 겨룬 6×6 표와 총점·순위가 나온다. 모든 전략이 결정론적이라 결과가 늘 같고, 축제 부스에서는 앙갚음 2225 · 늘 배신 2165 · 맞대응 2165 · 엇갈이 2120 · 너그러운 맞대응 2070 · 늘 협력 1950 으로 배신이 2등까지 올라오지만, 배신의 유혹이 5점뿐인 조별 과제에서는 앙갚음 5100 · 맞대응 5060 · 너그러운 맞대응 5030 · 늘 협력 4950 · 엇갈이 4810 · 늘 배신 4675 로 배신이 꼴찌가 된다. 문항 다섯: 늘 배신 대 늘 협력 600만원 / 맞대응 대 늘 배신 235만원(첫 판 10 + 아홉 판 25씩) / 맞대응이 덜 당하는 까닭 / 조별 과제 리그에서 늘 배신이 6등 / 보수가 바뀌면 순위가 뒤집히는 까닭. ④조건과 탈출 — R, T, P, S 네 손잡이를 0에서 100까지 움직이면 「상대가 협력할 때」와 「상대가 배신할 때」 어느 쪽이 유리한지 두 배지가 초록·빨강으로 바뀌고, 배신이 지배전략이면서 R > P 일 때만 「죄수의 딜레마」 배지가 뜬다. 협력이 지배전략(R > T 이고 S > P)인 판을 만드는 미션이 붙는다. 이어 축제 부스를 고정해 두고 벌금 손잡이를 올리면 배신했을 때의 보수에서만 벌금을 빼 T - f 와 P - f 가 되고, f > T - R = 20 과 f > P - S = 15 를 모두 넘기는 21만원에서 값 지키기가 지배전략이 되며 분홍 칸이 둘 다 배신 칸에서 둘 다 협력 칸으로 옮겨 간다. 문항 넷: 딜레마의 조건 T > R > P > S / 협력이 지배전략이 되는 두 조건 / 가장 작은 정수 벌금 21만원 / 반복·규칙·평판은 딜레마를 풀지만 서로를 모르게 막는 것은 오히려 굳힌다는 것. 상황과 숫자는 모두 개념을 보여 주기 위해 이 활동에서 정한 가상의 값임을 활동 안에 밝혀 두었다.$ov$, now()),
  ($s$economics/mini/extremum_lab$s$, $ov$함수의 증가·감소와 극대·극소를 '정의로 먼저 보고 도함수로 다시 보는' 다섯 탭으로 다루는 활동. ①두 점 재판소 — 다섯 함수의 구간마다 두 점을 끌어 함숫값만 견주고 990쌍을 전수 검사해 증가·감소를 정의 그대로 판정한다(증가·감소가 함수가 아니라 구간마다 정해지는 성질임을 확인한다). ②롤러코스터 — 네 코스의 트랙 위를 카트로 달리며 경사계와 앞쪽 풍경으로 오르막·내리막을 체감하고, 완주하면 드러나는 평평한 자리를 정상(극대)·골짜기(극소)·그냥 평평으로 분류한다. ③돋보기 창 — 점 a 둘레의 열린구간 폭 w 를 직접 좁혔다 넓히며 극대·극소의 정의에 나오는 '어떤 열린구간'의 뜻을 확인하고, x³-3x 의 극댓값 2 가 같은 구간의 최댓값 8.125 보다 작다는 것으로 극대와 최대를 구별한다. ④경사계와 증감표 — 접선을 끌어 f' 의 부호 띠를 칠해 가며 증감표를 완성하고, 이윤 곡선 P(q) = -q³ + 9q² - 15q 에서 q = 1 의 극솟값 -7 과 q = 5 의 극댓값 25 를 부호 변화로 찾는다. ⑤평평한 자리 분류소 — f'(a) = 0 인 여덟 자리(극대 3 · 극소 3 · 극값 아님 2)를 좌우 부호를 열어 가며 분류해, f'(x) > 0 이면 증가는 참이지만 그 역은 거짓이고 f'(a) = 0 만으로는 극값을 판정할 수 없음을 확인하는 활동. 이윤 곡선의 수치는 이 활동을 위해 정한 가상의 값이다.$ov$, now()),
  ($s$economics/mini/graph_shape_lab$s$, $ov$도함수로 함수의 그래프의 개형을 그리는 네 단계(도함수 구하기 → f'(x) = 0 인 x 찾기 → 좌우 부호로 극대·극소 판정 → 극값 구하기)를 다섯 탭으로 익히는 활동. ①증감표 탐정 — 증감표 하나에 후보 곡선 넷을 놓고 맞는 개형을 고른다. 틀린 셋은 극대·극소가 뒤바뀌거나, 극값의 x 나 값이 다르거나, 극값이 아예 없는 그래프여서 어디가 어긋나는지 짚게 한다. ②개형 공장 — x³-9x²+24x-10, -x³+6x²-9x+6, 3x⁴-8x³-6x²+24x 를 네 단계로 직접 밟는다. 도함수를 고르고 f'=0 인 x 를 입력하고 구간마다 부호를 토글한 뒤 극값을 구하면 곡선이 왼쪽부터 그려진다. ③공학도구 그래프판 — 식을 직접 입력하거나 계수 손잡이로 사차까지 그리고, [특징점]을 눌러 극값의 좌표를 확인하며 증감표가 자동으로 만들어지는 것을 본다. 극값이 2개·3개·0개인 함수를 직접 만들어 보는 미션이 있다. ④부호 카드 퍼즐 — 임계점 세 곳 사이의 네 구간에 + / - 카드를 놓으면 그 부호대로 곡선이 즉시 그려진다. 목표 네 모양의 부호 배열을 알아맞히며, 부호가 바뀌지 않는 '평평' 자리도 직접 만들어 본다. ⑤짝 맞추기 — f 다섯 장과 f' 다섯 장을 눈금 숫자 없이 모양만으로 짝짓는다. f'(x) = 0 은 극값의 후보일 뿐이고 좌우에서 부호가 바뀌어야 극값이 된다는 것을 다섯 탭에서 거듭 확인하는 활동.$ov$, now()),
  ($s$economics/mini/elasticity_lab$s$, $ov$수요의 가격 탄력성을 다섯 탭으로 다루는 활동. ①할인 실험실 — 무선 이어폰·우산·조각 케이크·보조배터리를 5~25% 할인해 보고, 가격의 변화율과 수요량의 변화율을 막대로 견주어 e = -(수요량 변화율)/(가격 변화율) 을 구한다. 네 상품의 e 는 차례로 2, 0.2, 1, 1.5 라 탄력적·비탄력적·단위 탄력적을 모두 만난다. ②좁혀 보기 — 할인폭을 20%에서 0.1%까지 줄이며 구간 탄력성이 점 탄력성 e = -x f'(x)/f(x) 로 모이는 것을 표로 본다. 일차 수요함수는 처음부터 같고(기울기가 늘 같아서), 쌍곡선형 3600/x 와 이차형 300-2x² 는 폭을 줄여야 참값 1 과 4 에 닿는다. ③탄력성 판별기 — 가격을 움직이며 e 를 읽고 1 을 기준으로 탄력적·단위 탄력적·비탄력적을 가린다. 같은 일차 수요함수라도 값이 쌀 때는 비탄력적이고 비쌀 때는 탄력적이며 단위 탄력점은 꼭 하나다. 2400/x 는 어디서나 1, 14400/x² 은 어디서나 2 라는 대비도 함께 본다. ④사장님의 선택 — 수요곡선과 수입 R = x f(x) 를 나란히 놓고 가장 많이 버는 가격을 찾는다. R'(x) = f(x)(1 - e) 이므로 수입의 꼭대기가 언제나 e = 1 인 가격과 같다는 것을 세 상품에서 확인한다. ⑤대체재 창고 — 브랜드 생수·배달 피자·해외여행 항공권·영화관 관람(탄력적)과 수돗물·통학 교통비·처방약·교복(비탄력적) 여덟 가지를 가르며, 대체재가 많을수록 탄력적이고 탄력적인 상품은 값을 올리면 수입이 줄어든다는 것을 겪는 활동. 수요함수와 변화율은 모두 이 활동을 위해 정한 가상의 값이다.$ov$, now()),
  ($s$economics/mini/supply_elasticity_lab$s$, $ov$공급의 가격 탄력성을 다섯 탭으로 다루는 활동. ①공장 실험실 — 탄산음료 공장·굴 양식장·도자기 공방·배달 기사의 가격을 5~25% 올려 보고 가격과 공급량의 변화율을 막대로 견주어 e = (공급량 변화율)/(가격 변화율) 을 구한다. 네 곳의 e 는 차례로 2, 0.5, 1, 2.5 이며, 두 변화율의 부호가 이미 같아 수요와 달리 음의 부호를 붙이지 않는다는 점을 확인한다. ②절편의 비밀 — f(x) = ax + b 의 a·b·가격을 손잡이로 움직이며, 일차 공급함수에서는 판정이 b 의 부호만으로 정해지고 가격과는 상관없다는 공급만의 성질을 찾아낸다. b < 0 이면 늘 탄력적, b = 0 이면 늘 단위 탄력적, b > 0 이면 늘 비탄력적이며, 공급선과 원점선의 기울기 비가 곧 탄력성임을 그림으로 본다(가격마다 판정이 달라지던 수요와 좋은 대조가 된다). ③좁혀 보기 — 인상폭을 20%에서 0.1%까지 줄이며 구간 탄력성이 점 탄력성 e = x f'(x)/f(x) 로 모이는 것을 표로 보고, f = kxⁿ 꼴은 지수 n 이 그대로 탄력성이 된다는 것을 확인한다. ④시간이 흐르면 — 딸기 농장·수제 가구 공방·편의점 도시락·도심 아파트의 값을 20% 올린 채 하루·일주일·한 달·한 해로 기간을 늘리면 공급곡선이 기준점을 축으로 점점 가팔라지며 탄력성이 커진다. 딸기는 한 해가 되어서야 탄력적이 되고 아파트는 한 해가 지나도 비탄력적으로 남는다. ⑤조절 속도 창고 — 창고의 티셔츠·전자책·전단지·호출 택시(탄력적)와 공연장 좌석·원유·숙성 와인·바닷가 땅(비탄력적) 여덟 가지를 가르며, 공급을 빨리 늘릴 수 있을수록 탄력적이라는 것을 겪는 활동. 공급함수와 변화율은 모두 이 활동을 위해 정한 가상의 값이다.$ov$, now()),
  ($s$economics/mini/elasticity_graph_lab$s$, $ov$탄력성을 그래프로 읽는 교과서의 두 활동을 구현해 네 탭으로 탐구하는 활동. ①두 기울기 재판소 — 곡선 위의 점을 움직이면 접선(분홍)과 원점선(노랑)이 함께 그려지고 두 기울기를 막대로 견준다. 탄력성이 (접선의 기울기) ÷ (원점선의 기울기) 임을 확인하고, 접선이 더 가파르면 탄력적, 원점선이 더 가파르면 비탄력적, 두 선이 포개지면 단위 탄력적임을 네 공급곡선에서 본다. ②중점의 비밀 — 일차 수요함수 f(x) = -ax + b 의 a 와 b 를 손잡이로 바꿔도 단위 탄력 가격이 늘 x 절편 A 와 y 절편 B 를 이은 선분의 중점임을 확인한다. 가격을 'x 절편 대비 비율 t' 로 잡아 t = 0.5 가 정확히 중점이 되게 했고, 곡선의 왼쪽 절반은 비탄력·오른쪽 절반은 탄력으로 색을 갈라 두었다. ③탄력성 자취 그리기 — 교과서의 공학도구 활동. 가격 t 를 끌거나 자동 재생하면 점 B(t, ε(t)) 가 자취를 남겨 탄력성이 하나의 곡선이 된다. 왼쪽에는 함수의 그래프, 오른쪽에는 그 자취를 나란히 두고, 자취가 가로선 y = 1 과 만나는 x 가 단위 탄력 가격임을 네 곡선에서 확인한다. 절편이 양수인 일차 공급곡선은 자취가 1 에 닿지 못한다는 대비도 함께 본다. ④탄력성 사격장 — 목표 탄력성(예 0.25 · 1 · 3)이 되는 가격을 0.1 눈금으로 정확히 맞히는 게임. 자취 위의 초록 선과 만나는 자리를 읽어 아홉 목표를 모두 명중시키며, 목표가 클수록 가격도 커진다는 것을 몸으로 익히는 활동. 함수와 수치는 모두 이 활동을 위해 정한 가상의 값이다.$ov$, now()),
  ($s$economics/mini/optimization_lab$s$, $ov$다양한 경제함수로 각 경제 주체의 의사 결정을 탐구하는 활동. ①최댓값 사냥 — 범위의 오른쪽 끝 b 를 손잡이로 움직이면 세 산(쌍봉산 x³ - 9x² + 15x + 50, 외봉산 -x³ + 3x² + 24x + 10, 민둥산 x³ + 3x + 10)에서 가장 높은 자리의 깃발이 봉우리와 끝 사이를 오간다. 도함수·f'(x) = 0 인 x·증감 부호 띠·개형·후보 견주기의 다섯 걸음이 손잡이를 따라 함께 갱신되고, 쌍봉산은 b = 7 에서 극댓값 57 과 오른쪽 끝의 함숫값이 꼭 같아지며 그보다 커지면 끝이 이긴다. 민둥산은 f'(x) = 3x² + 3 이 늘 양수여서 평평한 자리가 아예 없는 대비 사례다. 최댓값의 후보가 극댓값과 양 끝뿐이라는 것, 함수가 같아도 범위가 달라지면 답이 달라진다는 것을 확인한다. ②소비자의 선택 — 영화관 팝콘(-x³ + 6x² + 15x, 최적 5줌)·자전거 타기(-x³ + 3x² + 45x, 최적 50분)·컵케이크(-2x³ + 9x² + 24x, 최적 4개)·초콜릿(-2x³ + 15x² + 36x, 최적 6조각)의 효용함수에서 소비량을 늘리면 이모지가 쌓이고 만족도 막대와 접선이 함께 움직인다. 한계효용이 양수인 동안은 한 단위 더가 이득이고 0 이 되는 자리가 최적소비량이며 그 뒤로는 오히려 줄어듦을 본다. ③생산자의 선택 — 베이커리(-x³ + 9x² + 48x, 8명에 448개)·딸기 농장(-x³ + 6x² + 63x, 7명)·택배 분류장(-x³ + 3x² + 72x, 6명)·의류 공방(-2x³ + 3x² + 72x, 4명)에서 일손을 늘려 보며 한계생산량이 0 이 되는 최적노동량을 찾고, 그 자리를 넘기면 한 명 더 넣을 때 생산량이 실제로 몇 개 줄어드는지 확인한다. ④기업의 선택 — 쿠키 공방(값 40, 비용 x³ - 6x² + 25x + 20)·향초 공방(값 50)·화분 공방(값 35)에서 총수입 직선과 총비용 곡선을 한 그림에 두고 그 사이의 세로 간격이 곧 이윤임을 굵은 막대로 보여 준다. 오른쪽에는 이윤함수를 따로 그려 적자 구간, 손익분기점, 이윤이 가장 큰 최적생산량(쿠키 5상자에 80)을 짚는다. ⑤한계비용 = 가격 — 식빵(x² + 10x + 16)·주스(2x² + 6x + 32)·얼음(3x² + 12x + 27) 공장에서 시장 가격 p 를 올리면 비용 곡선의 접선이 수입 직선과 나란해지는 자리가 오른쪽으로 옮겨 간다. h'(x) = p - g'(x) = 0 에서 g'(x) = p 가 나오는 까닭을 식과 그림으로 함께 보고, 가격을 바꿀 때마다 쌓이는 짝 (최적생산량, 가격)이 모두 한계비용 직선 위에 올라앉아 그것이 곧 공급곡선임을 확인한다. 식빵 공장은 가장 큰 이윤이 꼭 0 이 되는 가격이 18 이어서 그보다 값이 낮으면 어떤 생산량으로도 적자를 벗어날 수 없다. 함수와 금액은 모두 이 활동을 위해 정한 가상의 값이다.$ov$, now())
